/* Original practice question bank.
   domainId: "fund" (A+/Network+ refresher) or "d1".."d5"
   type: "single" (one correct answer) or "multi" (exactly the number stated in the prompt)
   Every question includes an explanation for the correct answer and a
   short reason for every wrong choice, per the rubric's assessment rules. */

const QUESTIONS = [
  // ---------- FUNDAMENTALS CHECK (12) ----------
  { id: "q-f1", domainId: "fund", tag: "f-boot-process", type: "single",
    prompt: "A technician wants to ensure only digitally signed, trusted bootloaders can run when a laptop starts. Which UEFI feature should be enabled?",
    choices: [ {id:"a", text:"Secure Boot"}, {id:"b", text:"Fast Startup"}, {id:"c", text:"Legacy BIOS mode"}, {id:"d", text:"POST logging"} ],
    correct: "a",
    explanation: "Secure Boot is the UEFI feature that only allows cryptographically signed, trusted code to execute during startup, blocking bootkits/rootkits.",
    distractorExplanations: { b: "Fast Startup affects shutdown/boot speed behavior, not trust verification.", c: "Legacy BIOS mode disables modern UEFI features, including Secure Boot.", d: "POST logging would just record hardware self-test results, not enforce signature checks." } },
  { id: "q-f2", domainId: "fund", tag: "f-os-fundamentals", type: "single",
    prompt: "An administrator gives a new help-desk technician only the access needed to reset passwords, and nothing more. This best demonstrates which concept?",
    choices: [ {id:"a", text:"Least privilege"}, {id:"b", text:"Accounting"}, {id:"c", text:"Non-repudiation"}, {id:"d", text:"Availability"} ],
    correct: "a",
    explanation: "Least privilege means granting only the minimum access necessary to perform a job function.",
    distractorExplanations: { b: "Accounting is about logging/recording actions taken, not limiting access.", c: "Non-repudiation is about proving someone can't deny an action, unrelated here.", d: "Availability concerns systems being accessible/usable, not access scope." } },
  { id: "q-f3", domainId: "fund", tag: "f-command-line", type: "single",
    prompt: "Which command would show the hop-by-hop path packets take to reach a remote server?",
    choices: [ {id:"a", text:"tracert / traceroute"}, {id:"b", text:"ping"}, {id:"c", text:"netstat"}, {id:"d", text:"nslookup"} ],
    correct: "a",
    explanation: "tracert (Windows) / traceroute (Linux/macOS) reports each router hop along the path to a destination.",
    distractorExplanations: { b: "ping only tests basic reachability, not the path taken.", c: "netstat shows active connections/listening ports on the local machine.", d: "nslookup queries DNS records; it doesn't trace a network path." } },
  { id: "q-f4", domainId: "fund", tag: "f-file-permissions", type: "single",
    prompt: "A file server stores sensitive HR documents. Which file system choice provides native support for granular permissions and encryption?",
    choices: [ {id:"a", text:"NTFS"}, {id:"b", text:"FAT32"}, {id:"c", text:"exFAT"}, {id:"d", text:"None of these support permissions"} ],
    correct: "a",
    explanation: "NTFS supports detailed access control lists (ACLs) and native encryption (EFS), making it appropriate for sensitive data.",
    distractorExplanations: { b: "FAT32 has no built-in permission or encryption model.", c: "exFAT, like FAT32, lacks native permission/encryption support.", d: "NTFS does support permissions, so this is incorrect." } },
  { id: "q-f5", domainId: "fund", tag: "f-patching", type: "single",
    prompt: "Why does publishing a security patch create urgency for organizations to apply it quickly?",
    choices: [ {id:"a", text:"The vulnerability the patch fixes becomes publicly documented, so attackers can study and exploit it"}, {id:"b", text:"Patches always improve system performance"}, {id:"c", text:"Patches are only released once a year"}, {id:"d", text:"Unpatched systems automatically get flagged by antivirus software"} ],
    correct: "a",
    explanation: "Once a patch is released, the vulnerability it addresses is typically publicly disclosed, giving attackers a roadmap to exploit systems that haven't applied it yet.",
    distractorExplanations: { b: "Performance is not the reason urgency exists; security exposure is.", c: "Patches are released on varying schedules, not once a year.", d: "Antivirus does not automatically flag unpatched systems." } },
  { id: "q-f6", domainId: "fund", tag: "f-virtualization", type: "single",
    prompt: "An attacker manages to break out of a virtual machine and gain access to the underlying host system. What is this called?",
    choices: [ {id:"a", text:"VM escape"}, {id:"b", text:"Snapshot rollback"}, {id:"c", text:"Live migration"}, {id:"d", text:"Containerization"} ],
    correct: "a",
    explanation: "VM escape describes an attacker breaking out of an isolated virtual machine to access the host or other VMs.",
    distractorExplanations: { b: "A snapshot rollback restores a VM to a prior saved state; it's not an attack.", c: "Live migration moves a running VM between physical hosts for maintenance, not an attack.", d: "Containerization is a different virtualization approach, not this specific attack." } },
  { id: "q-f7", domainId: "fund", tag: "f-osi-tcpip", type: "single",
    prompt: "A firewall rule blocks traffic based on destination port number. At which OSI layer does this filtering primarily occur?",
    choices: [ {id:"a", text:"Layer 4 (Transport)"}, {id:"b", text:"Layer 2 (Data Link)"}, {id:"c", text:"Layer 7 (Application)"}, {id:"d", text:"Layer 1 (Physical)"} ],
    correct: "a",
    explanation: "Port numbers are a Transport-layer (Layer 4) concept, used by TCP/UDP to identify services.",
    distractorExplanations: { b: "Layer 2 deals with MAC addresses and switches, not ports.", c: "Layer 7 filtering would inspect application content, not just port numbers.", d: "Layer 1 concerns physical cabling/signaling, unrelated to ports." } },
  { id: "q-f8", domainId: "fund", tag: "f-ip-subnetting", type: "single",
    prompt: "Which of the following is a private IPv4 address range?",
    choices: [ {id:"a", text:"192.168.0.0/16"}, {id:"b", text:"8.8.8.0/24"}, {id:"c", text:"93.184.216.0/24"}, {id:"d", text:"1.1.1.0/24"} ],
    correct: "a",
    explanation: "192.168.0.0/16 is one of the RFC 1918 private address ranges, not routable on the public Internet.",
    distractorExplanations: { b: "8.8.8.0/24 is a public range (associated with Google's public DNS).", c: "93.184.216.0/24 is a public range.", d: "1.1.1.0/24 is a public range (associated with Cloudflare's public DNS)." } },
  { id: "q-f9", domainId: "fund", tag: "f-ports-protocols", type: "single",
    prompt: "Which port is associated with encrypted web traffic (HTTPS)?",
    choices: [ {id:"a", text:"443"}, {id:"b", text:"80"}, {id:"c", text:"21"}, {id:"d", text:"23"} ],
    correct: "a",
    explanation: "Port 443 is the well-known port for HTTPS (HTTP over TLS).",
    distractorExplanations: { b: "Port 80 is unencrypted HTTP.", c: "Port 21 is FTP control (unencrypted).", d: "Port 23 is Telnet (unencrypted remote login)." } },
  { id: "q-f10", domainId: "fund", tag: "f-dns-dhcp", type: "single",
    prompt: "An attacker sets up an unauthorized DHCP server on a network to hand out a malicious default gateway to new devices. What is this called?",
    choices: [ {id:"a", text:"Rogue DHCP server"}, {id:"b", text:"DNS record"}, {id:"c", text:"CIDR block"}, {id:"d", text:"Subnet mask"} ],
    correct: "a",
    explanation: "A rogue DHCP server is an unauthorized DHCP service that can hand out malicious configuration, such as a fake gateway used to intercept traffic.",
    distractorExplanations: { b: "A DNS record maps names to addresses; it's unrelated to DHCP address assignment.", c: "A CIDR block describes address space notation, not a rogue service.", d: "A subnet mask defines network/host boundaries, not an attack technique." } },
  { id: "q-f11", domainId: "fund", tag: "f-routing-switching-vlans", type: "single",
    prompt: "Two devices are on different VLANs on the same physical switch. What is required for them to communicate?",
    choices: [ {id:"a", text:"A router or Layer 3 switch to route between the VLANs"}, {id:"b", text:"Nothing — VLANs on the same switch always communicate freely"}, {id:"c", text:"A DNS server"}, {id:"d", text:"A DHCP relay agent"} ],
    correct: "a",
    explanation: "VLANs are isolated broadcast domains; a router or Layer 3 switch is required to route traffic between them.",
    distractorExplanations: { b: "This is the opposite of how VLANs work — isolation is the point of using them.", c: "DNS resolves names to addresses; it doesn't route between VLANs.", d: "A DHCP relay forwards DHCP requests across subnets, but doesn't itself enable general VLAN-to-VLAN communication." } },
  { id: "q-f12", domainId: "fund", tag: "f-firewall-nat-vpn-wifi", type: "single",
    prompt: "Which technology allows multiple internal devices with private IP addresses to share a single public IP address to reach the Internet?",
    choices: [ {id:"a", text:"NAT"}, {id:"b", text:"VPN"}, {id:"c", text:"VLAN"}, {id:"d", text:"WPA3"} ],
    correct: "a",
    explanation: "NAT (Network Address Translation) translates private internal addresses to a shared public address for Internet access.",
    distractorExplanations: { b: "A VPN creates an encrypted tunnel; it doesn't perform address translation for Internet sharing.", c: "A VLAN segments a network logically; it doesn't provide address translation.", d: "WPA3 is a wireless encryption standard, unrelated to address translation." } },

  // ---------- DOMAIN 1: General Security Concepts (10) ----------
  { id: "q-d1-1", domainId: "d1", tag: "d1-flagship", type: "single",
    prompt: "A company installs a fence around its data center. What category and function best describe this control?",
    choices: [ {id:"a", text:"Physical, preventive"}, {id:"b", text:"Technical, detective"}, {id:"c", text:"Managerial, directive"}, {id:"d", text:"Operational, corrective"} ],
    correct: "a",
    explanation: "A fence is a tangible physical barrier (category: physical) that stops unauthorized access before it happens (function: preventive).",
    distractorExplanations: { b: "A fence isn't technology-based, and it stops access rather than just detecting it.", c: "A fence isn't a policy document; it's a physical barrier.", d: "A fence isn't a human process, and it prevents rather than corrects." } },
  { id: "q-d1-2", domainId: "d1", tag: "d1-flagship", type: "single",
    prompt: "A visible security camera in a parking lot discourages some people from attempting theft, even though it doesn't physically stop anyone. What function does this control primarily serve?",
    choices: [ {id:"a", text:"Deterrent"}, {id:"b", text:"Preventive"}, {id:"c", text:"Corrective"}, {id:"d", text:"Compensating"} ],
    correct: "a",
    explanation: "A control that discourages an action without physically stopping it is a deterrent control.",
    distractorExplanations: { b: "Preventive controls physically stop the action; a camera alone doesn't.", c: "Corrective controls fix damage after an incident; a camera doesn't fix anything.", d: "Compensating controls stand in for a primary control that can't be used, which isn't the scenario described." } },
  { id: "q-d1-3", domainId: "d1", tag: "d1-t2", type: "single",
    prompt: "Which principle ensures that a user who submitted a digitally signed request cannot credibly deny having done so?",
    choices: [ {id:"a", text:"Non-repudiation"}, {id:"b", text:"Availability"}, {id:"c", text:"Least privilege"}, {id:"d", text:"Obfuscation"} ],
    correct: "a",
    explanation: "Non-repudiation provides assurance that an action can be tied to its originator, who cannot credibly deny performing it.",
    distractorExplanations: { b: "Availability concerns systems being accessible, unrelated to denying actions.", c: "Least privilege concerns minimal access, not proof of action.", d: "Obfuscation makes something harder to understand; it doesn't prove authorship." } },
  { id: "q-d1-4", domainId: "d1", tag: "d1-t2", type: "single",
    prompt: "In a zero trust architecture, which statement is most accurate?",
    choices: [ {id:"a", text:"Every access request is verified, regardless of whether it originates inside or outside the network"}, {id:"b", text:"Users inside the corporate network are automatically trusted"}, {id:"c", text:"Zero trust eliminates the need for authentication"}, {id:"d", text:"Zero trust only applies to cloud environments"} ],
    correct: "a",
    explanation: "Zero trust assumes no implicit trust for any user or device, inside or outside the network, and continuously verifies every request.",
    distractorExplanations: { b: "This is the opposite of zero trust, which rejects automatic trust based on network location.", c: "Zero trust relies heavily on strong authentication, not its elimination.", d: "Zero trust principles apply to on-premises environments too, not only cloud." } },
  { id: "q-d1-5", domainId: "d1", tag: "d1-t3", type: "single",
    prompt: "Before applying a firewall rule change in production, an administrator documents a way to quickly undo the change if it causes problems. What is this called?",
    choices: [ {id:"a", text:"Rollback plan"}, {id:"b", text:"Risk register"}, {id:"c", text:"Chain of custody"}, {id:"d", text:"Business impact analysis"} ],
    correct: "a",
    explanation: "A rollback plan is a predefined way to reverse a change if it causes unexpected problems.",
    distractorExplanations: { b: "A risk register tracks identified risks, not change reversal steps.", c: "Chain of custody concerns evidence handling in investigations.", d: "A business impact analysis identifies critical functions and dependencies, not change rollback." } },
  { id: "q-d1-6", domainId: "d1", tag: "d1-t4", type: "single",
    prompt: "An organization needs to securely store user passwords so that even if the database is stolen, the original passwords are extremely difficult to recover. Which technique is most appropriate?",
    choices: [ {id:"a", text:"Salted hashing with key stretching"}, {id:"b", text:"Base64 encoding"}, {id:"c", text:"Symmetric encryption with a hardcoded key"}, {id:"d", text:"Plaintext storage with access controls"} ],
    correct: "a",
    explanation: "Salted hashing (with key stretching like bcrypt/PBKDF2) is the standard for password storage: it's one-way, resists rainbow tables, and slows brute-force attempts.",
    distractorExplanations: { b: "Base64 is reversible encoding, not security — anyone can decode it instantly.", c: "A hardcoded symmetric key is a poor practice; if the key leaks, all passwords are exposed and reversible.", d: "Plaintext storage exposes passwords immediately if the database is breached, regardless of access controls." } },
  { id: "q-d1-7", domainId: "d1", tag: "d1-t4", type: "single",
    prompt: "A vendor needs to prove that a downloaded update file truly came from them and was not modified in transit. Which cryptographic tool best addresses this?",
    choices: [ {id:"a", text:"Digital signature"}, {id:"b", text:"Symmetric encryption"}, {id:"c", text:"Data masking"}, {id:"d", text:"Tokenization"} ],
    correct: "a",
    explanation: "A digital signature, created with the sender's private key and verified with their public key, proves authenticity and integrity.",
    distractorExplanations: { b: "Symmetric encryption protects confidentiality, not proof of origin/integrity.", c: "Data masking hides part of sensitive data for display purposes, unrelated to proving authorship.", d: "Tokenization replaces sensitive data with a placeholder; it doesn't prove file origin." } },
  { id: "q-d1-8", domainId: "d1", tag: "d1-t2", type: "multi",
    prompt: "Which TWO of the following are examples of deception technology used to study attackers without risking real assets?",
    choices: [ {id:"a", text:"Honeypot"}, {id:"b", text:"Honeytoken"}, {id:"c", text:"Firewall"}, {id:"d", text:"VPN concentrator"} ],
    correct: ["a", "b"],
    explanation: "Honeypots (decoy systems) and honeytokens (decoy data/credentials) are both deception techniques designed to lure and detect attackers.",
    distractorExplanations: { c: "A firewall filters traffic; it's a preventive control, not deception technology.", d: "A VPN concentrator terminates VPN connections; it's not deception technology." } },
  { id: "q-d1-9", domainId: "d1", tag: "d1-flagship", type: "single",
    prompt: "A company can't immediately replace an old application that lacks MFA support, so it places the app behind a jump server that itself requires MFA. What kind of control is the jump server acting as in this scenario?",
    choices: [ {id:"a", text:"Compensating control"}, {id:"b", text:"Directive control"}, {id:"c", text:"Deterrent control"}, {id:"d", text:"Physical control"} ],
    correct: "a",
    explanation: "Because the ideal control (MFA on the app itself) isn't feasible, the jump server with MFA is a compensating control providing similar protection.",
    distractorExplanations: { b: "A directive control is a mandate/policy, not a technical stand-in measure.", c: "A deterrent only discourages; this control actively enforces an authentication requirement.", d: "This is a technical control (a server enforcing MFA), not a physical barrier." } },
  { id: "q-d1-10", domainId: "d1", tag: "d1-t3", type: "single",
    prompt: "Which statement best describes the purpose of impact analysis during change management?",
    choices: [ {id:"a", text:"Determine what systems, users, or processes could be affected by a proposed change before it's approved"}, {id:"b", text:"Encrypt the change request document"}, {id:"c", text:"Automatically approve low-risk changes without review"}, {id:"d", text:"Replace the need for testing"} ],
    correct: "a",
    explanation: "Impact analysis evaluates what could be affected by a change so stakeholders can make an informed approval decision.",
    distractorExplanations: { b: "Encryption protects confidentiality of documents; it isn't the purpose of impact analysis.", c: "Impact analysis informs review; it doesn't replace approval with automation.", d: "Impact analysis and testing are separate, complementary steps in the process." } },

  // ---------- DOMAIN 2: Threats, Vulnerabilities, and Mitigations (18) ----------
  { id: "q-d2-1", domainId: "d2", tag: "d2-t1", type: "single",
    prompt: "An employee uses an unapproved personal cloud storage account to share work files because the official system feels slow. This is an example of:",
    choices: [ {id:"a", text:"Shadow IT"}, {id:"b", text:"Insider threat with malicious intent"}, {id:"c", text:"Nation-state activity"}, {id:"d", text:"Hacktivism"} ],
    correct: "a",
    explanation: "Shadow IT is the use of unapproved technology within an organization; it's typically not malicious, but it creates risk because it's outside security's visibility and control.",
    distractorExplanations: { b: "This is not described as intentionally malicious; it's a convenience-driven policy violation.", c: "Nothing indicates sophisticated, state-sponsored activity.", d: "Hacktivism involves ideological motivation, not present in this scenario." } },
  { id: "q-d2-2", domainId: "d2", tag: "d2-t1", type: "single",
    prompt: "A group breaches a company's website and defaces it with a political message, without seeking financial gain. Which threat actor type does this best describe?",
    choices: [ {id:"a", text:"Hacktivist"}, {id:"b", text:"Organized crime"}, {id:"c", text:"Unskilled attacker"}, {id:"d", text:"Competitor"} ],
    correct: "a",
    explanation: "Hacktivists are motivated by ideology or a cause, often using disruption or embarrassment (like defacement) rather than financial gain.",
    distractorExplanations: { b: "Organized crime is primarily financially motivated.", c: "The skill level isn't indicated; the motivation (political) is the defining clue here.", d: "A competitor would typically pursue business advantage/espionage, not political messaging." } },
  { id: "q-d2-3", domainId: "d2", tag: "d2-t2", type: "single",
    prompt: "Which action most directly reduces an organization's attack surface?",
    choices: [ {id:"a", text:"Disabling unused services and removing default accounts"}, {id:"b", text:"Increasing the number of open ports for convenience"}, {id:"c", text:"Adding more administrator accounts"}, {id:"d", text:"Extending password expiration to one year"} ],
    correct: "a",
    explanation: "Disabling unused services and removing default accounts eliminates unnecessary exposure, directly shrinking the attack surface.",
    distractorExplanations: { b: "Opening more ports increases, not decreases, the attack surface.", c: "More administrator accounts increases risk exposure, not reduces it.", d: "Longer password expiration doesn't relate to attack surface size." } },
  { id: "q-d2-4", domainId: "d2", tag: "d2-t3", type: "single",
    prompt: "A web application fails to validate user input before including it in a database query, allowing an attacker to manipulate the query. This is an example of:",
    choices: [ {id:"a", text:"Injection vulnerability"}, {id:"b", text:"Buffer overflow"}, {id:"c", text:"Race condition"}, {id:"d", text:"VM escape"} ],
    correct: "a",
    explanation: "Injection (such as SQL injection) occurs when untrusted input is passed into a query/command without proper validation, letting an attacker alter its behavior.",
    distractorExplanations: { b: "A buffer overflow involves writing beyond allocated memory, not query manipulation.", c: "A race condition is a timing-dependent flaw, not input validation failure.", d: "VM escape is a virtualization vulnerability, unrelated to query handling." } },
  { id: "q-d2-5", domainId: "d2", tag: "d2-t3", type: "single",
    prompt: "An attacker injects a malicious script into a comment field on a website, which then executes in the browser of every visitor who views that comment. This is:",
    choices: [ {id:"a", text:"Cross-Site Scripting (XSS)"}, {id:"b", text:"Cross-Site Request Forgery (CSRF)"}, {id:"c", text:"Server-Side Request Forgery (SSRF)"}, {id:"d", text:"Directory traversal"} ],
    correct: "a",
    explanation: "XSS involves injecting malicious script that executes in other users' browsers when they view the affected page.",
    distractorExplanations: { b: "CSRF tricks a logged-in user's browser into submitting an unwanted request; it doesn't involve injecting a script that runs for other viewers.", c: "SSRF tricks a server into making requests on the attacker's behalf, not a browser-side script issue.", d: "Directory traversal accesses files outside an intended folder, unrelated to script injection." } },
  { id: "q-d2-6", domainId: "d2", tag: "d2-t4", type: "single",
    prompt: "Malware that encrypts a victim's files and demands payment for the decryption key is called:",
    choices: [ {id:"a", text:"Ransomware"}, {id:"b", text:"Worm"}, {id:"c", text:"Rootkit"}, {id:"d", text:"Spyware"} ],
    correct: "a",
    explanation: "Ransomware encrypts victim data and demands payment (ransom) for restoring access.",
    distractorExplanations: { b: "A worm self-replicates across a network; encryption-for-ransom isn't its defining trait.", c: "A rootkit hides deep in the OS to maintain access; it doesn't necessarily encrypt files for ransom.", d: "Spyware secretly gathers information; it doesn't hold data for ransom." } },
  { id: "q-d2-7", domainId: "d2", tag: "d2-t4", type: "single",
    prompt: "An attacker tries the single password \"Summer2024!\" against thousands of different user accounts to avoid triggering account lockout thresholds. This technique is called:",
    choices: [ {id:"a", text:"Password spraying"}, {id:"b", text:"Credential stuffing"}, {id:"c", text:"Rainbow table attack"}, {id:"d", text:"Dictionary attack"} ],
    correct: "a",
    explanation: "Password spraying tries one (or a few) common passwords across many accounts, deliberately avoiding the repeated failed attempts on a single account that would trigger lockout.",
    distractorExplanations: { b: "Credential stuffing uses previously leaked username/password pairs, not a single guessed password.", c: "A rainbow table attack reverses hashed passwords using precomputed tables, a different technique entirely.", d: "A dictionary attack tries many candidate passwords against one account, the reverse pattern of spraying." } },
  { id: "q-d2-8", domainId: "d2", tag: "d2-t4", type: "single",
    prompt: "Which network attack involves an attacker secretly intercepting and possibly altering communication between two parties who believe they're talking directly to each other?",
    choices: [ {id:"a", text:"On-path (man-in-the-middle) attack"}, {id:"b", text:"DDoS attack"}, {id:"c", text:"Evil twin attack"}, {id:"d", text:"DNS poisoning"} ],
    correct: "a",
    explanation: "An on-path (man-in-the-middle) attack places the attacker between two communicating parties, intercepting or altering traffic without their knowledge.",
    distractorExplanations: { b: "A DDoS attack overwhelms a target to deny service; it doesn't involve intercepting communication.", c: "An evil twin is a fake wireless access point mimicking a legitimate one — a specific setup technique, more specific than the general on-path concept described.", d: "DNS poisoning corrupts DNS answers to redirect users; it's a different mechanism than directly intercepting an established conversation." } },
  { id: "q-d2-9", domainId: "d2", tag: "d2-flagship", type: "single",
    prompt: "An email appears to come from the company CEO, urgently instructing the finance team to wire funds immediately, bypassing normal approval steps. This scenario primarily combines which social engineering elements?",
    choices: [ {id:"a", text:"Authority and urgency"}, {id:"b", text:"Tailgating and shoulder surfing"}, {id:"c", text:"Baiting with a physical device"}, {id:"d", text:"Vishing only"} ],
    correct: "a",
    explanation: "This is Business Email Compromise, exploiting the authority of a senior figure and urgency to pressure the target into bypassing normal procedures.",
    distractorExplanations: { b: "Tailgating and shoulder surfing are in-person physical techniques, not described here.", c: "Baiting involves a tempting physical or digital lure like a USB drive, not described here.", d: "The scenario is delivered by email, not a voice call, so it isn't vishing." } },
  { id: "q-d2-10", domainId: "d2", tag: "d2-flagship", type: "single",
    prompt: "An attacker calls the help desk pretending to be a locked-out employee, giving a fabricated but believable story to convince the technician to reset a password without proper verification. What is the fabricated story itself called?",
    choices: [ {id:"a", text:"Pretexting"}, {id:"b", text:"Whaling"}, {id:"c", text:"Smishing"}, {id:"d", text:"Typosquatting"} ],
    correct: "a",
    explanation: "Pretexting is inventing a believable fabricated scenario to manipulate a victim into an action, such as bypassing verification.",
    distractorExplanations: { b: "Whaling specifically targets senior executives; this scenario targets a help desk, not an executive.", c: "Smishing is phishing via SMS text message; this scenario is a phone call.", d: "Typosquatting registers misspelled domain names to trick users, unrelated to this phone-based scenario." } },
  { id: "q-d2-11", domainId: "d2", tag: "d2-flagship", type: "single",
    prompt: "A phishing message is specifically crafted using researched details about one targeted employee, referencing their manager's name and a real ongoing project. This is best described as:",
    choices: [ {id:"a", text:"Spear phishing"}, {id:"b", text:"Generic phishing"}, {id:"c", text:"Smishing"}, {id:"d", text:"Vishing"} ],
    correct: "a",
    explanation: "Spear phishing is personalized and targeted at a specific individual using researched, believable details, unlike generic mass phishing.",
    distractorExplanations: { b: "Generic phishing is broad and untargeted, not personalized like this scenario.", c: "Smishing is delivered via SMS, not email as described.", d: "Vishing is delivered via voice call, not email as described." } },
  { id: "q-d2-12", domainId: "d2", tag: "d2-t5", type: "single",
    prompt: "Which mitigation technique specifically limits how far an attacker can move after compromising one system, by dividing the network into isolated zones?",
    choices: [ {id:"a", text:"Segmentation"}, {id:"b", text:"Patching"}, {id:"c", text:"User training"}, {id:"d", text:"Hashing"} ],
    correct: "a",
    explanation: "Segmentation divides a network into zones, limiting lateral movement after an initial compromise.",
    distractorExplanations: { b: "Patching closes known vulnerabilities but doesn't limit post-compromise movement by itself.", c: "User training reduces the likelihood of social engineering success, not lateral movement.", d: "Hashing verifies integrity; it's unrelated to network movement restriction." } },
  { id: "q-d2-13", domainId: "d2", tag: "d2-t3", type: "single",
    prompt: "A vulnerability that has no available patch and is unknown to the vendor at the time it's discovered and exploited is called:",
    choices: [ {id:"a", text:"A zero-day"}, {id:"b", text:"A legacy vulnerability"}, {id:"c", text:"A false positive"}, {id:"d", text:"A compensating control"} ],
    correct: "a",
    explanation: "A zero-day is a vulnerability unknown to the vendor (or with no available patch) at the time of exploitation.",
    distractorExplanations: { b: "A legacy vulnerability affects outdated systems, often with a known but unapplied fix — different from an unknown, unpatched flaw.", c: "A false positive is an incorrect alert, unrelated to vulnerability disclosure status.", d: "A compensating control is a mitigation stand-in, not a vulnerability type." } },
  { id: "q-d2-14", domainId: "d2", tag: "d2-t4", type: "multi",
    prompt: "Which TWO of the following are examples of malware that can spread or operate without requiring direct user action to execute?",
    choices: [ {id:"a", text:"Worm"}, {id:"b", text:"Fileless malware"}, {id:"c", text:"Trojan"}, {id:"d", text:"Adware requiring manual install"} ],
    correct: ["a", "b"],
    explanation: "Worms self-replicate across a network without user action, and fileless malware often executes via memory-resident techniques (e.g., abusing legitimate system tools) without a traditional user-triggered file execution.",
    distractorExplanations: { c: "A trojan disguises itself as legitimate software and typically requires the user to run it.", d: "Manually installed adware, by definition, requires direct user action to install." } },
  { id: "q-d2-15", domainId: "d2", tag: "d2-t2", type: "single",
    prompt: "An employee finds a USB drive labeled \"Payroll 2024\" in the parking lot and plugs it into their work computer out of curiosity. This vector is best described as:",
    choices: [ {id:"a", text:"Baiting via removable media"}, {id:"b", text:"Whaling"}, {id:"c", text:"On-path attack"}, {id:"d", text:"DNS poisoning"} ],
    correct: "a",
    explanation: "Baiting uses a tempting item (here, a labeled USB drive) to lure a victim into an unsafe action; removable media is a classic delivery vector.",
    distractorExplanations: { b: "Whaling targets senior executives via phishing; nothing here indicates that.", c: "An on-path attack intercepts communication between two parties; unrelated to a found USB drive.", d: "DNS poisoning corrupts DNS resolution, unrelated to this physical media scenario." } },
  { id: "q-d2-16", domainId: "d2", tag: "d2-t3", type: "single",
    prompt: "An attacker tricks a vulnerable server into making an internal network request on the attacker's behalf, reaching internal systems the attacker couldn't access directly. This is:",
    choices: [ {id:"a", text:"Server-Side Request Forgery (SSRF)"}, {id:"b", text:"Cross-Site Scripting (XSS)"}, {id:"c", text:"Directory traversal"}, {id:"d", text:"Buffer overflow"} ],
    correct: "a",
    explanation: "SSRF tricks a server into making unintended requests, often reaching internal resources the attacker can't access directly.",
    distractorExplanations: { b: "XSS injects script that runs in other users' browsers, not server-side requests.", c: "Directory traversal accesses files outside an intended directory, not network requests.", d: "A buffer overflow is a memory-handling flaw, unrelated to server-side request manipulation." } },
  { id: "q-d2-17", domainId: "d2", tag: "d2-t1", type: "single",
    prompt: "Which threat actor category typically has the greatest access to funding, tools, and time, often pursuing long-term espionage goals?",
    choices: [ {id:"a", text:"Nation-state"}, {id:"b", text:"Unskilled attacker"}, {id:"c", text:"Hacktivist"}, {id:"d", text:"Shadow IT"} ],
    correct: "a",
    explanation: "Nation-state actors typically have the highest resources, sophistication, and patience, often for espionage or strategic disruption.",
    distractorExplanations: { b: "Unskilled attackers have low sophistication and rely on existing tools.", c: "Hacktivists are ideology-driven and generally less resourced than nation-states.", d: "Shadow IT isn't a threat actor at all — it's unapproved technology use, usually without malicious intent." } },
  { id: "q-d2-18", domainId: "d2", tag: "d2-t5", type: "single",
    prompt: "A company only allows explicitly approved applications to run on employee workstations, blocking everything else by default. This is an example of:",
    choices: [ {id:"a", text:"Allowlisting"}, {id:"b", text:"Blocklisting"}, {id:"c", text:"Tokenization"}, {id:"d", text:"Load balancing"} ],
    correct: "a",
    explanation: "Allowlisting permits only explicitly approved items (here, applications) and blocks everything else by default.",
    distractorExplanations: { b: "Blocklisting does the opposite — it blocks known-bad items and allows everything else by default.", c: "Tokenization replaces sensitive data with placeholders; unrelated to application control.", d: "Load balancing distributes traffic across servers; unrelated to application control." } },

  // ---------- DOMAIN 3: Security Architecture (14) ----------
  { id: "q-d3-1", domainId: "d3", tag: "d3-flagship", type: "single",
    prompt: "A company places its public-facing web server in a network segment that is neither fully trusted nor fully exposed to the Internet, separate from the internal network. This segment is called:",
    choices: [ {id:"a", text:"DMZ / screened subnet"}, {id:"b", text:"VLAN trunk"}, {id:"c", text:"Air gap"}, {id:"d", text:"Loopback network"} ],
    correct: "a",
    explanation: "A DMZ (or screened subnet) hosts public-facing services in a semi-trusted zone, separating them from the fully trusted internal network.",
    distractorExplanations: { b: "A VLAN trunk carries multiple VLANs over one link; it's not itself a trust zone.", c: "An air gap means no network connectivity at all, the opposite of hosting an Internet-facing server.", d: "A loopback network refers to a device talking to itself; unrelated to this scenario." } },
  { id: "q-d3-2", domainId: "d3", tag: "d3-flagship", type: "single",
    prompt: "Administrators are required to connect only through a single, heavily monitored and hardened server before reaching any internal production system. This server is called a:",
    choices: [ {id:"a", text:"Bastion host / jump server"}, {id:"b", text:"Load balancer"}, {id:"c", text:"DNS resolver"}, {id:"d", text:"Honeypot"} ],
    correct: "a",
    explanation: "A bastion host (jump server) is a hardened, controlled single entry point for administrative access to internal systems.",
    distractorExplanations: { b: "A load balancer distributes traffic across servers for performance/availability, not administrative access control.", c: "A DNS resolver handles name resolution, unrelated to access control.", d: "A honeypot is a decoy system to lure attackers, not a legitimate access path." } },
  { id: "q-d3-3", domainId: "d3", tag: "d3-flagship", type: "single",
    prompt: "Traffic flowing directly between two servers within the same internal network zone is best described as:",
    choices: [ {id:"a", text:"East-west traffic"}, {id:"b", text:"North-south traffic"}, {id:"c", text:"Out-of-band traffic"}, {id:"d", text:"Broadcast traffic"} ],
    correct: "a",
    explanation: "East-west traffic refers to traffic moving within the same network zone, such as server to server.",
    distractorExplanations: { b: "North-south traffic moves between different zones, such as internal network to Internet.", c: "Out-of-band traffic uses a separate management channel, a different concept entirely.", d: "Broadcast traffic is sent to all devices on a segment, not specifically server-to-server communication." } },
  { id: "q-d3-4", domainId: "d3", tag: "d3-t1", type: "single",
    prompt: "In a SaaS (Software as a Service) model, which security responsibility typically remains with the customer under the shared responsibility model?",
    choices: [ {id:"a", text:"Managing user access and data classification within the application"}, {id:"b", text:"Patching the underlying physical servers"}, {id:"c", text:"Securing the data center's physical access"}, {id:"d", text:"Maintaining the hypervisor"} ],
    correct: "a",
    explanation: "In SaaS, the provider manages the infrastructure and application, but the customer is still responsible for managing their own users, access, and data classification within the service.",
    distractorExplanations: { b: "Patching underlying servers is the provider's responsibility in SaaS.", c: "Physical data center security is the provider's responsibility.", d: "Hypervisor maintenance is the provider's responsibility, not the customer's." } },
  { id: "q-d3-5", domainId: "d3", tag: "d3-t1", type: "single",
    prompt: "Which characteristic distinguishes containers from traditional virtual machines?",
    choices: [ {id:"a", text:"Containers share the host OS kernel, making them more lightweight than VMs"}, {id:"b", text:"Containers require a separate physical server for each instance"}, {id:"c", text:"Containers cannot be used in cloud environments"}, {id:"d", text:"Containers always provide stronger isolation than VMs"} ],
    correct: "a",
    explanation: "Containers share the host OS kernel rather than including a full guest OS, making them more lightweight than traditional VMs.",
    distractorExplanations: { b: "Containers do not require a dedicated physical server each; that's not how they achieve lightweight deployment.", c: "Containers are heavily used in cloud environments.", d: "VMs generally provide stronger isolation than containers, since containers share the kernel." } },
  { id: "q-d3-6", domainId: "d3", tag: "d3-t3", type: "single",
    prompt: "A company displays only the last four digits of a customer's credit card number on receipts, while the full number is stored securely elsewhere. This display technique is called:",
    choices: [ {id:"a", text:"Masking"}, {id:"b", text:"Hashing"}, {id:"c", text:"Tokenization"}, {id:"d", text:"Obfuscation of source code"} ],
    correct: "a",
    explanation: "Masking hides part of sensitive data (like showing only the last four digits) while the full value remains stored elsewhere.",
    distractorExplanations: { b: "Hashing is a one-way transformation used for integrity verification, not partial display.", c: "Tokenization replaces the entire value with a token that maps back to the original in a secure system — not simply displaying part of it.", d: "Obfuscation of source code refers to making code hard to read, unrelated to displaying card numbers." } },
  { id: "q-d3-7", domainId: "d3", tag: "d3-t3", type: "single",
    prompt: "Which tool is specifically designed to detect and block sensitive data from leaving an organization through email or file uploads?",
    choices: [ {id:"a", text:"DLP (Data Loss Prevention)"}, {id:"b", text:"NAT"}, {id:"c", text:"Load balancer"}, {id:"d", text:"VLAN"} ],
    correct: "a",
    explanation: "DLP tools detect and block sensitive data from leaving an organization improperly, such as through email or uploads.",
    distractorExplanations: { b: "NAT translates addresses for Internet access, unrelated to content inspection.", c: "A load balancer distributes traffic for performance, not content inspection.", d: "A VLAN segments a network logically; it doesn't inspect data leaving the organization." } },
  { id: "q-d3-8", domainId: "d3", tag: "d3-t4", type: "single",
    prompt: "An organization can tolerate at most 4 hours of downtime for its order system, but can lose no more than 15 minutes of transaction data. Which two metrics describe these two requirements, respectively?",
    choices: [ {id:"a", text:"RTO = 4 hours; RPO = 15 minutes"}, {id:"b", text:"RPO = 4 hours; RTO = 15 minutes"}, {id:"c", text:"MTTR = 4 hours; MTBF = 15 minutes"}, {id:"d", text:"SLE = 4 hours; ARO = 15 minutes"} ],
    correct: "a",
    explanation: "RTO (Recovery Time Objective) measures acceptable downtime (4 hours). RPO (Recovery Point Objective) measures acceptable data loss (15 minutes).",
    distractorExplanations: { b: "This reverses the definitions — RPO is data loss, RTO is downtime.", c: "MTTR/MTBF measure actual repair time and failure frequency, not target objectives set by the business.", d: "SLE/ARO are monetary loss and occurrence rate figures, not time-based recovery targets." } },
  { id: "q-d3-9", domainId: "d3", tag: "d3-t4", type: "single",
    prompt: "Which backup type creates the fastest backup job but the slowest restore, since it requires the last full backup plus every incremental backup since then?",
    choices: [ {id:"a", text:"Incremental backup"}, {id:"b", text:"Full backup"}, {id:"c", text:"Differential backup"}, {id:"d", text:"Snapshot backup"} ],
    correct: "a",
    explanation: "Incremental backups only copy data changed since the last backup (full or incremental), making backup fast, but restore requires the full backup plus every subsequent increment, making restore slow.",
    distractorExplanations: { b: "A full backup is the slowest to create but fastest to restore, the opposite tradeoff.", c: "A differential backup requires only the full backup plus the latest differential, restoring faster than incremental.", d: "A snapshot backup captures a point-in-time state, a different mechanism than this tradeoff description." } },
  { id: "q-d3-10", domainId: "d3", tag: "d3-t4", type: "single",
    prompt: "A recovery site has basic power and cooling but no servers or data pre-installed, requiring equipment to be shipped and configured before use. This is a:",
    choices: [ {id:"a", text:"Cold site"}, {id:"b", text:"Hot site"}, {id:"c", text:"Warm site"}, {id:"d", text:"Mirrored site"} ],
    correct: "a",
    explanation: "A cold site provides only basic infrastructure; everything else must be brought in and set up before it's operational.",
    distractorExplanations: { b: "A hot site is fully equipped and ready to take over almost immediately.", c: "A warm site is partially equipped, needing some setup time, but more ready than a cold site.", d: "A mirrored site is essentially a live-replicated hot site, the most ready option, not this scenario." } },
  { id: "q-d3-11", domainId: "d3", tag: "d3-t2b", type: "single",
    prompt: "Which technology combines networking and security policy enforcement into a single cloud-delivered service, well-suited to organizations with many remote users and cloud applications?",
    choices: [ {id:"a", text:"SASE"}, {id:"b", text:"NAT"}, {id:"c", text:"VLAN"}, {id:"d", text:"POP3"} ],
    correct: "a",
    explanation: "SASE (Secure Access Service Edge) combines networking (like SD-WAN) and security functions into one cloud-delivered service.",
    distractorExplanations: { b: "NAT is address translation, not a combined networking/security service model.", c: "A VLAN is a Layer 2 segmentation technique, not a cloud-delivered service model.", d: "POP3 is an email retrieval protocol, unrelated to this concept." } },
  { id: "q-d3-12", domainId: "d3", tag: "d3-t1", type: "single",
    prompt: "An industrial control system (ICS) managing a water treatment plant is rarely patched immediately, even when vulnerabilities are known. What best explains this common tradeoff?",
    choices: [ {id:"a", text:"ICS/SCADA systems often prioritize continuous availability and safety, making patching riskier and more carefully scheduled"}, {id:"b", text:"ICS systems are immune to vulnerabilities"}, {id:"c", text:"Patching ICS systems is against the law"}, {id:"d", text:"ICS systems don't run software"} ],
    correct: "a",
    explanation: "ICS/SCADA environments often prioritize uptime and physical safety, so patching is scheduled cautiously to avoid disrupting critical, sometimes safety-critical, operations.",
    distractorExplanations: { b: "ICS systems are not immune to vulnerabilities — this is a real, well-known risk category.", c: "Patching ICS systems is not illegal; the caution is operational, not legal.", d: "ICS systems do run software/firmware; that's exactly why patching is a relevant concern." } },
  { id: "q-d3-13", domainId: "d3", tag: "d3-t4", type: "single",
    prompt: "A disaster recovery plan is tested by having stakeholders talk through their responses to a simulated scenario in a conference room, without touching any live systems. This is a:",
    choices: [ {id:"a", text:"Tabletop exercise"}, {id:"b", text:"Failover test"}, {id:"c", text:"Restoration test"}, {id:"d", text:"Penetration test"} ],
    correct: "a",
    explanation: "A tabletop exercise is a discussion-based walkthrough of a scenario, testing understanding and plans without disrupting live systems.",
    distractorExplanations: { b: "A failover test actually triggers systems to switch to a backup site/system.", c: "A restoration test actually restores data/systems from backup to verify it works.", d: "A penetration test involves active attempted exploitation, unrelated to this discussion-based exercise." } },
  { id: "q-d3-14", domainId: "d3", tag: "d3-t3", type: "single",
    prompt: "A regulation requires that a company's customer data physically remain stored within a specific country's borders. This requirement relates to:",
    choices: [ {id:"a", text:"Data sovereignty / residency"}, {id:"b", text:"Data masking"}, {id:"c", text:"Data tokenization"}, {id:"d", text:"Data hashing"} ],
    correct: "a",
    explanation: "Data sovereignty/residency concerns where data is legally stored and which country's laws apply to it.",
    distractorExplanations: { b: "Data masking hides part of a value for display; unrelated to physical storage location.", c: "Tokenization replaces sensitive values with tokens; unrelated to storage location requirements.", d: "Hashing is a one-way integrity check; unrelated to storage location requirements." } },

  // ---------- DOMAIN 4: Security Operations (22) ----------
  { id: "q-d4-1", domainId: "d4", tag: "d4-flagship", type: "single",
    prompt: "Put the incident response phases in the correct order: Containment, Detection, Eradication, Preparation, Recovery, Analysis, Lessons Learned.",
    choices: [
      {id:"a", text:"Preparation, Detection, Analysis, Containment, Eradication, Recovery, Lessons Learned"},
      {id:"b", text:"Detection, Preparation, Containment, Analysis, Eradication, Recovery, Lessons Learned"},
      {id:"c", text:"Preparation, Containment, Detection, Analysis, Recovery, Eradication, Lessons Learned"},
      {id:"d", text:"Analysis, Detection, Preparation, Containment, Recovery, Eradication, Lessons Learned"} ],
    correct: "a",
    explanation: "The correct order is Preparation, Detection, Analysis, Containment, Eradication, Recovery, Lessons Learned.",
    distractorExplanations: { b: "Preparation must come before Detection — you build the plan and tools before an incident occurs.", c: "Analysis must occur before Containment decisions, and Eradication must occur before Recovery.", d: "Preparation must be first, and Analysis follows Detection, not before it." } },
  { id: "q-d4-2", domainId: "d4", tag: "d4-flagship", type: "single",
    prompt: "During an investigation, which type of evidence should typically be collected FIRST, according to order of volatility?",
    choices: [ {id:"a", text:"Data in RAM"}, {id:"b", text:"Data on the hard disk"}, {id:"c", text:"Archived log files on a remote server"}, {id:"d", text:"Printed documentation"} ],
    correct: "a",
    explanation: "Order of volatility says to collect the most easily lost evidence first — RAM contents disappear when a system is powered off, so it should be captured before disk or remote data.",
    distractorExplanations: { b: "Disk data is less volatile than RAM and should be collected after RAM.", c: "Remote archived logs are typically the least volatile and can be collected later.", d: "Printed documentation isn't volatile digital evidence at all in this context." } },
  { id: "q-d4-3", domainId: "d4", tag: "d4-flagship", type: "single",
    prompt: "An analyst documents exactly who handled a piece of digital evidence, when, and what was done with it, from collection through storage. This documentation is called:",
    choices: [ {id:"a", text:"Chain of custody"}, {id:"b", text:"Order of volatility"}, {id:"c", text:"Root-cause analysis"}, {id:"d", text:"Business impact analysis"} ],
    correct: "a",
    explanation: "Chain of custody is the documented, unbroken record of who handled evidence and when, proving it wasn't tampered with.",
    distractorExplanations: { b: "Order of volatility describes the sequence for collecting evidence, not custody documentation.", c: "Root-cause analysis identifies why an incident happened, not evidence handling records.", d: "Business impact analysis identifies critical business functions, unrelated to evidence documentation." } },
  { id: "q-d4-4", domainId: "d4", tag: "d4-t3", type: "single",
    prompt: "A vulnerability scan is performed while logged into systems with valid accounts, revealing more detailed results with fewer false positives than an external-only scan. This is a:",
    choices: [ {id:"a", text:"Credentialed scan"}, {id:"b", text:"Non-credentialed scan"}, {id:"c", text:"Intrusive scan"}, {id:"d", text:"Penetration test"} ],
    correct: "a",
    explanation: "A credentialed scan logs into systems with valid credentials, providing deeper, more accurate results than an external-only view.",
    distractorExplanations: { b: "A non-credentialed scan only sees what's visible externally, without logging in.", c: "Intrusive vs non-intrusive describes whether the scan actively tests exploitation, a different distinction.", d: "A penetration test involves actual attempted exploitation by a human, beyond automated scanning." } },
  { id: "q-d4-5", domainId: "d4", tag: "d4-t3", type: "single",
    prompt: "A scanner reports a critical CVE on a server, but that server is isolated, offline, and holds no sensitive data. How should this finding most likely be prioritized?",
    choices: [ {id:"a", text:"Lower priority than the raw CVSS score suggests, because business context and exposure reduce real risk"}, {id:"b", text:"Always the highest priority, regardless of context, because the CVSS score is critical"}, {id:"c", text:"Ignored completely and never documented"}, {id:"d", text:"Immediately reported to law enforcement"} ],
    correct: "a",
    explanation: "Prioritization should combine CVSS severity with business context — an isolated, low-value, offline system has much lower real-world risk than the raw score alone suggests.",
    distractorExplanations: { b: "Ignoring context and using only the raw score leads to poor prioritization decisions.", c: "It should still be documented and tracked, even if deprioritized, not ignored completely.", d: "A vulnerability finding on an isolated internal server doesn't warrant law enforcement involvement." } },
  { id: "q-d4-6", domainId: "d4", tag: "d4-t4", type: "single",
    prompt: "A SOC has configured alerts so sensitively that analysts receive hundreds of low-value notifications daily, causing them to start ignoring alerts, including real ones. This describes:",
    choices: [ {id:"a", text:"Alert fatigue"}, {id:"b", text:"A false negative"}, {id:"c", text:"A zero-day"}, {id:"d", text:"Segmentation"} ],
    correct: "a",
    explanation: "Alert fatigue occurs when excessive alerting desensitizes analysts, increasing the risk that real incidents get missed.",
    distractorExplanations: { b: "A false negative is a single missed detection, not the broader desensitization pattern described.", c: "A zero-day is an unpatched, unknown vulnerability, unrelated to alert volume.", d: "Segmentation is a network design control, unrelated to alerting behavior." } },
  { id: "q-d4-7", domainId: "d4", tag: "d4-t4", type: "single",
    prompt: "Why is accurate time synchronization (e.g., via NTP) critical across all systems being monitored?",
    choices: [ {id:"a", text:"It allows analysts to correlate events across different logs accurately, in the correct order"}, {id:"b", text:"It encrypts log data automatically"}, {id:"c", text:"It prevents all malware infections"}, {id:"d", text:"It is required for DHCP to function"} ],
    correct: "a",
    explanation: "Consistent time synchronization lets analysts correctly correlate events across multiple log sources during an investigation.",
    distractorExplanations: { b: "Time synchronization doesn't encrypt data; it's unrelated to encryption.", c: "Time sync has no effect on preventing malware infections.", d: "DHCP does not depend on time synchronization to function." } },
  { id: "q-d4-8", domainId: "d4", tag: "d4-t5", type: "single",
    prompt: "Which control verifies that a device meets an organization's security requirements (such as up-to-date antivirus and patches) before granting it network access?",
    choices: [ {id:"a", text:"NAC (Network Access Control)"}, {id:"b", text:"DLP"}, {id:"c", text:"SIEM"}, {id:"d", text:"IDS"} ],
    correct: "a",
    explanation: "NAC checks a device's security posture against policy requirements before allowing it onto the network.",
    distractorExplanations: { b: "DLP prevents sensitive data from leaving an organization, unrelated to device posture checks.", c: "SIEM aggregates and correlates logs; it doesn't gate network access.", d: "An IDS detects suspicious traffic; it doesn't gate initial network access based on device posture." } },
  { id: "q-d4-9", domainId: "d4", tag: "d4-t6", type: "single",
    prompt: "An organization removes a departing employee's system access immediately as part of their offboarding checklist. This is an example of:",
    choices: [ {id:"a", text:"Deprovisioning"}, {id:"b", text:"Provisioning"}, {id:"c", text:"Federation"}, {id:"d", text:"Just-in-time access"} ],
    correct: "a",
    explanation: "Deprovisioning is the timely removal of access when an employee leaves or changes roles.",
    distractorExplanations: { b: "Provisioning is creating accounts and granting initial access, the opposite process.", c: "Federation allows identities to be trusted across separate organizations/systems, unrelated to offboarding.", d: "Just-in-time access grants temporary elevated access when needed, a different concept from offboarding." } },
  { id: "q-d4-10", domainId: "d4", tag: "d4-t6", type: "single",
    prompt: "A finance process requires one employee to create a payment request and a different employee to approve it, so no single person can both create and approve fraudulent payments. This demonstrates:",
    choices: [ {id:"a", text:"Separation of duties"}, {id:"b", text:"Single sign-on"}, {id:"c", text:"Federation"}, {id:"d", text:"Just-in-time access"} ],
    correct: "a",
    explanation: "Separation of duties divides a sensitive process among multiple people so no single person has complete control, reducing fraud/error risk.",
    distractorExplanations: { b: "Single sign-on lets one identity access multiple systems; unrelated to dividing responsibilities.", c: "Federation extends trust across organizations; unrelated to dividing a process between roles.", d: "Just-in-time access grants temporary elevated permissions; unrelated to this scenario." } },
  { id: "q-d4-11", domainId: "d4", tag: "d4-t6", type: "multi",
    prompt: "Which TWO of the following are valid examples of MFA (multi-factor authentication) factor categories?",
    choices: [ {id:"a", text:"Something you know (a password)"}, {id:"b", text:"Something you are (a fingerprint)"}, {id:"c", text:"Something you already told someone"}, {id:"d", text:"Something everyone can access"} ],
    correct: ["a", "b"],
    explanation: "The standard MFA factor categories include something you know (password/PIN), something you have (token/phone), and something you are (biometric).",
    distractorExplanations: { c: "This isn't a recognized MFA factor category.", d: "Something everyone can access would provide no real authentication security — it isn't a valid factor category." } },
  { id: "q-d4-12", domainId: "d4", tag: "d4-t7", type: "single",
    prompt: "A SOAR playbook automatically isolates any workstation that triggers three specific high-severity SIEM alerts within five minutes, without waiting for human review. What is a key RISK of this kind of full automation?",
    choices: [ {id:"a", text:"A misconfigured rule or bad input could trigger incorrect automated actions at scale before a human catches it"}, {id:"b", text:"Automation always improves accuracy with no downsides"}, {id:"c", text:"Automation eliminates the need for a SIEM entirely"}, {id:"d", text:"Playbooks cannot be updated once created"} ],
    correct: "a",
    explanation: "A core automation risk is that bad input or a misconfigured rule can cause incorrect actions to happen quickly and at scale, before a human notices — this is the 'automation blast radius' concept.",
    distractorExplanations: { b: "Automation has real tradeoffs and risks; it isn't universally without downside.", c: "SOAR relies on SIEM (or similar) alerts as triggers; it doesn't eliminate the need for it.", d: "Playbooks can and should be updated/reviewed over time." } },
  { id: "q-d4-13", domainId: "d4", tag: "d4-t9", type: "single",
    prompt: "An analyst wants to determine which internal device held a specific IP address at the time of a suspicious connection. Which log source is most directly useful?",
    choices: [ {id:"a", text:"DHCP logs"}, {id:"b", text:"MX records"}, {id:"c", text:"CVSS scores"}, {id:"d", text:"Risk register"} ],
    correct: "a",
    explanation: "DHCP logs record which device (by MAC address) was assigned a given IP address at a given time — exactly what's needed here.",
    distractorExplanations: { b: "MX records identify mail servers for a domain, unrelated to IP-to-device mapping.", c: "CVSS scores rate vulnerability severity, unrelated to this lookup.", d: "A risk register tracks organizational risks, unrelated to this technical lookup." } },
  { id: "q-d4-14", domainId: "d4", tag: "d4-t9", type: "single",
    prompt: "In a log entry, a legitimate word-processing application is shown as the parent process of an unexpected command-line tool launching a PowerShell script. Why is this combination suspicious?",
    choices: [ {id:"a", text:"A normal document-editing app spawning a scripting/command tool is an unusual parent-child process pairing, often indicating exploitation"}, {id:"b", text:"Word processors are never allowed to run at all"}, {id:"c", text:"PowerShell is always malicious by definition"}, {id:"d", text:"This pattern always indicates a hardware failure"} ],
    correct: "a",
    explanation: "Unusual parent-child process relationships, such as an office application spawning a scripting tool, are a recognized indicator of exploitation (e.g., a malicious macro).",
    distractorExplanations: { b: "Word processors are normal, allowed applications; the issue is the unusual child process, not the app itself.", c: "PowerShell is a legitimate administrative tool; it's the unusual context that's suspicious, not the tool itself.", d: "This is a software/security indicator, not a hardware failure indicator." } },
  { id: "q-d4-15", domainId: "d4", tag: "d4-t1", type: "single",
    prompt: "A company issues employees corporate-owned phones but allows personal use of those devices. This device strategy is called:",
    choices: [ {id:"a", text:"COPE (Corporate-Owned, Personally Enabled)"}, {id:"b", text:"BYOD (Bring Your Own Device)"}, {id:"c", text:"CYOD (Choose Your Own Device)"}, {id:"d", text:"Shadow IT"} ],
    correct: "a",
    explanation: "COPE describes company-owned devices that are also permitted for personal use.",
    distractorExplanations: { b: "BYOD means the device is employee-owned, not company-owned.", c: "CYOD means the employee selects from a company-approved list, but the ownership arrangement differs from COPE.", d: "Shadow IT refers to unapproved technology use, unrelated to a formal device program." } },
  { id: "q-d4-16", domainId: "d4", tag: "d4-t2", type: "single",
    prompt: "Before disposing of old hard drives, an organization uses a certified process to ensure data cannot be recovered from them. This process is called:",
    choices: [ {id:"a", text:"Sanitization"}, {id:"b", text:"Provisioning"}, {id:"c", text:"Classification"}, {id:"d", text:"Federation"} ],
    correct: "a",
    explanation: "Sanitization securely erases data from media so it cannot be recovered, appropriate before disposal or reuse.",
    distractorExplanations: { b: "Provisioning refers to creating accounts/access, unrelated to media disposal.", c: "Classification labels data by sensitivity, a separate step from disposal.", d: "Federation relates to identity trust across systems, unrelated to media disposal." } },
  { id: "q-d4-17", domainId: "d4", tag: "d4-flagship", type: "single",
    prompt: "After a malware infection is fully removed and the exploited vulnerability is patched, the affected server is restored to production and closely monitored. This phase is:",
    choices: [ {id:"a", text:"Recovery"}, {id:"b", text:"Containment"}, {id:"c", text:"Eradication"}, {id:"d", text:"Detection"} ],
    correct: "a",
    explanation: "Recovery restores affected systems to normal, verified operation after the root cause has been eradicated.",
    distractorExplanations: { b: "Containment limits spread while the incident is active, before eradication.", c: "Eradication is the removal of the root cause itself, which in this scenario has already happened.", d: "Detection is identifying that something suspicious occurred, the earliest phase, not this one." } },
  { id: "q-d4-18", domainId: "d4", tag: "d4-t5", type: "single",
    prompt: "An analyst isolates a potentially compromised endpoint from the network but keeps it powered on and preserved for forensic review, rather than immediately wiping it. This response level is best described as:",
    choices: [ {id:"a", text:"Quarantine"}, {id:"b", text:"Ignore"}, {id:"c", text:"Full eradication"}, {id:"d", text:"Escalation to law enforcement"} ],
    correct: "a",
    explanation: "Quarantine isolates a system while preserving it for further analysis, rather than destroying evidence or taking no action.",
    distractorExplanations: { b: "Ignoring the alert would mean taking no action at all, not isolating and preserving the system.", c: "Full eradication implies removing the cause already, but this scenario is still in an isolation/analysis step.", d: "Escalation to law enforcement is a separate, situational decision not implied simply by isolating a device." } },
  { id: "q-d4-19", domainId: "d4", tag: "d4-t3", type: "single",
    prompt: "Which term describes a publicly known, standardized identifier assigned to a specific software vulnerability?",
    choices: [ {id:"a", text:"CVE"}, {id:"b", text:"ALE"}, {id:"c", text:"RTO"}, {id:"d", text:"SLA"} ],
    correct: "a",
    explanation: "CVE (Common Vulnerabilities and Exposures) is a standardized identifier for a publicly known vulnerability.",
    distractorExplanations: { b: "ALE is a risk-quantification metric (Annualized Loss Expectancy), unrelated to vulnerability identifiers.", c: "RTO is a recovery time metric, unrelated to vulnerability identifiers.", d: "An SLA is a vendor service agreement, unrelated to vulnerability identifiers." } },
  { id: "q-d4-20", domainId: "d4", tag: "d4-t7", type: "single",
    prompt: "What is the primary benefit organizations seek from automating repeatable security workflows like initial alert triage?",
    choices: [ {id:"a", text:"Speed, consistency, and reduced manual error at scale"}, {id:"b", text:"Eliminating the need for any security staff"}, {id:"c", text:"Guaranteeing zero false positives"}, {id:"d", text:"Removing the need for logging"} ],
    correct: "a",
    explanation: "Automation's core benefits are speed, consistency, and scale, with reduced manual error — not the elimination of staff, false positives, or logging.",
    distractorExplanations: { b: "Automation supports staff; it doesn't eliminate the need for skilled analysts, especially for judgment calls.", c: "Automation doesn't guarantee zero false positives; tuning is still required.", d: "Logging remains essential regardless of automation." } },
  { id: "q-d4-21", domainId: "d4", tag: "d4-t4", type: "single",
    prompt: "Which tool is best described as collecting and correlating log data from across an organization to support detection and reporting?",
    choices: [ {id:"a", text:"SIEM"}, {id:"b", text:"EDR"}, {id:"c", text:"DLP"}, {id:"d", text:"VPN"} ],
    correct: "a",
    explanation: "SIEM (Security Information and Event Management) collects and correlates logs organization-wide for detection and reporting.",
    distractorExplanations: { b: "EDR focuses on individual endpoint detection and response, narrower than org-wide log correlation.", c: "DLP prevents sensitive data exfiltration, a different function than log correlation.", d: "A VPN provides encrypted remote connectivity, unrelated to log correlation." } },
  { id: "q-d4-22", domainId: "d4", tag: "d4-t1", type: "single",
    prompt: "A documented, hardened, known-good starting configuration that systems are built from is called a:",
    choices: [ {id:"a", text:"Secure baseline"}, {id:"b", text:"Risk register"}, {id:"c", text:"Playbook"}, {id:"d", text:"Chain of custody"} ],
    correct: "a",
    explanation: "A secure baseline is a documented, hardened, known-good configuration used as the starting point for systems.",
    distractorExplanations: { b: "A risk register tracks identified risks, unrelated to system configuration.", c: "A playbook defines incident response steps, not a base configuration.", d: "Chain of custody concerns evidence handling, unrelated to system configuration." } },

  // ---------- DOMAIN 5: Security Program Management and Oversight (16) ----------
  { id: "q-d5-1", domainId: "d5", tag: "d5-flagship", type: "single",
    prompt: "A company estimates a specific type of security incident would cost 400,000 pesos each time it occurs, and expects it to happen twice per year. What is the ALE?",
    choices: [ {id:"a", text:"800,000 pesos"}, {id:"b", text:"400,000 pesos"}, {id:"c", text:"200,000 pesos"}, {id:"d", text:"1,600,000 pesos"} ],
    correct: "a",
    explanation: "ALE = SLE x ARO = 400,000 x 2 = 800,000 pesos expected loss per year.",
    distractorExplanations: { b: "This is just the SLE, without multiplying by the annual occurrence rate.", c: "This incorrectly divides rather than multiplies SLE by ARO.", d: "This overstates the calculation; 400,000 x 2 is 800,000, not 1,600,000." } },
  { id: "q-d5-2", domainId: "d5", tag: "d5-flagship", type: "single",
    prompt: "A company decides a specific risk's potential cost is lower than the cost of any available control, and formally documents the decision to take no further action. This is:",
    choices: [ {id:"a", text:"Risk acceptance"}, {id:"b", text:"Risk avoidance"}, {id:"c", text:"Risk transfer"}, {id:"d", text:"Risk mitigation"} ],
    correct: "a",
    explanation: "Risk acceptance is a formal, documented decision to take no further action because the cost of treating the risk outweighs the potential loss.",
    distractorExplanations: { b: "Risk avoidance means stopping the activity that causes the risk entirely, not documented inaction.", c: "Risk transfer shifts the impact to another party, such as insurance — not described here.", d: "Risk mitigation actively reduces the risk with a control, the opposite of what's described." } },
  { id: "q-d5-3", domainId: "d5", tag: "d5-flagship", type: "single",
    prompt: "A company decides to stop offering a risky product feature entirely rather than manage the risk it introduces. This risk treatment is:",
    choices: [ {id:"a", text:"Avoidance"}, {id:"b", text:"Mitigation"}, {id:"c", text:"Transfer"}, {id:"d", text:"Acceptance"} ],
    correct: "a",
    explanation: "Avoidance eliminates a risk by stopping the activity that causes it entirely.",
    distractorExplanations: { b: "Mitigation reduces risk with a control while continuing the activity, not stopping it.", c: "Transfer shifts financial impact elsewhere, such as insurance, not stopping the activity.", d: "Acceptance means continuing with no further action, not stopping the activity." } },
  { id: "q-d5-4", domainId: "d5", tag: "d5-t1", type: "single",
    prompt: "Which governance document provides mandatory, specific technical requirements supporting a broader policy, such as \"all data at rest must use AES-256\"?",
    choices: [ {id:"a", text:"Standard"}, {id:"b", text:"Guideline"}, {id:"c", text:"Policy"}, {id:"d", text:"Procedure"} ],
    correct: "a",
    explanation: "A standard provides mandatory, specific requirements that support a higher-level policy.",
    distractorExplanations: { b: "A guideline is recommended, not mandatory.", c: "A policy is a high-level, general statement of intent, not a specific technical requirement.", d: "A procedure is step-by-step instructions for a task, not a stated requirement." } },
  { id: "q-d5-5", domainId: "d5", tag: "d5-t1", type: "single",
    prompt: "Which governance document type is recommended best-practice advice, but is NOT mandatory?",
    choices: [ {id:"a", text:"Guideline"}, {id:"b", text:"Policy"}, {id:"c", text:"Standard"}, {id:"d", text:"Procedure"} ],
    correct: "a",
    explanation: "A guideline offers recommended, non-mandatory best-practice advice.",
    distractorExplanations: { b: "A policy is mandatory, high-level intent.", c: "A standard is mandatory and specific.", d: "A procedure is mandatory, step-by-step instructions." } },
  { id: "q-d5-6", domainId: "d5", tag: "d5-t3", type: "single",
    prompt: "A contract clause allows a company to inspect a vendor's security practices directly. This is called a:",
    choices: [ {id:"a", text:"Right-to-audit clause"}, {id:"b", text:"Service Level Agreement (SLA)"}, {id:"c", text:"Non-Disclosure Agreement (NDA)"}, {id:"d", text:"Memorandum of Understanding (MOU)"} ],
    correct: "a",
    explanation: "A right-to-audit clause contractually allows an organization to audit a vendor's security practices.",
    distractorExplanations: { b: "An SLA defines expected service performance levels, not audit rights.", c: "An NDA protects confidentiality of shared information, not audit rights.", d: "An MOU is a broader working agreement, not specifically an audit right." } },
  { id: "q-d5-7", domainId: "d5", tag: "d5-t3", type: "single",
    prompt: "An organization relies entirely on a single vendor for a critical cloud service, with no alternative provider identified. This exposes the organization to:",
    choices: [ {id:"a", text:"Concentration risk"}, {id:"b", text:"Risk transfer"}, {id:"c", text:"Data minimization risk"}, {id:"d", text:"Non-repudiation risk"} ],
    correct: "a",
    explanation: "Concentration risk arises from relying too heavily on a single vendor, creating a single point of failure.",
    distractorExplanations: { b: "Risk transfer is a treatment strategy, not a risk category itself.", c: "Data minimization is a privacy principle, unrelated to vendor reliance.", d: "Non-repudiation is a security property about proving actions, unrelated to vendor reliance." } },
  { id: "q-d5-8", domainId: "d5", tag: "d5-t4", type: "single",
    prompt: "A privacy principle stating that an organization should only collect the data actually necessary for its stated purpose is called:",
    choices: [ {id:"a", text:"Data minimization"}, {id:"b", text:"Data sovereignty"}, {id:"c", text:"Data masking"}, {id:"d", text:"Data tokenization"} ],
    correct: "a",
    explanation: "Data minimization means collecting only the data necessary for the stated purpose.",
    distractorExplanations: { b: "Data sovereignty concerns where data is legally stored, not how much is collected.", c: "Data masking hides part of a value for display, unrelated to collection scope.", d: "Tokenization replaces sensitive values with tokens, unrelated to collection scope." } },
  { id: "q-d5-9", domainId: "d5", tag: "d5-t5", type: "single",
    prompt: "A team is authorized to actively attempt to breach an organization's defenses to test them, while another team defends and responds in real time, and both teams later share findings to improve overall security. What are these two teams called, respectively?",
    choices: [ {id:"a", text:"Red team and blue team"}, {id:"b", text:"Purple team and green team"}, {id:"c", text:"White team and black team"}, {id:"d", text:"Gold team and silver team"} ],
    correct: "a",
    explanation: "The red team attacks (offense) and the blue team defends; when they collaborate to improve both sides, that collaboration is often called purple teaming.",
    distractorExplanations: { b: "Purple describes the collaboration between red and blue, not a separate attacking/defending pair; green team isn't a standard term here.", c: "White team/black team aren't the standard offense/defense pairing used in this context.", d: "Gold team/silver team aren't standard security testing team names." } },
  { id: "q-d5-10", domainId: "d5", tag: "d5-t5", type: "single",
    prompt: "Before a penetration test begins, the client and testing team agree in writing on exactly what systems may be tested, what techniques are allowed, and the testing window. This document is called:",
    choices: [ {id:"a", text:"Rules of engagement"}, {id:"b", text:"Risk register"}, {id:"c", text:"Incident report"}, {id:"d", text:"Service Level Agreement"} ],
    correct: "a",
    explanation: "Rules of engagement document the agreed scope and boundaries of an authorized security test before it begins.",
    distractorExplanations: { b: "A risk register tracks organizational risks generally, not test-specific boundaries.", c: "An incident report documents a security incident after the fact, not pre-test agreements.", d: "An SLA defines expected service performance, not testing boundaries." } },
  { id: "q-d5-11", domainId: "d5", tag: "d5-t5", type: "single",
    prompt: "An independent outside firm reviews an organization's security controls and issues a formal attestation for regulators and customers. This is best described as:",
    choices: [ {id:"a", text:"An external audit"}, {id:"b", text:"An internal audit"}, {id:"c", text:"A tabletop exercise"}, {id:"d", text:"A vulnerability scan"} ],
    correct: "a",
    explanation: "An external audit is performed by an independent outside party, often producing more credible attestation for external stakeholders.",
    distractorExplanations: { b: "An internal audit is performed by the organization's own staff, not an outside firm.", c: "A tabletop exercise tests incident response plans through discussion, not a compliance attestation.", d: "A vulnerability scan is an automated technical check, not a formal audit/attestation." } },
  { id: "q-d5-12", domainId: "d5", tag: "d5-t6", type: "single",
    prompt: "A company measures the success of its security awareness program by tracking the decline in employees clicking simulated phishing links over time, rather than just attendance at training sessions. Why is this the better approach?",
    choices: [ {id:"a", text:"It measures actual behavioral outcomes, not just participation"}, {id:"b", text:"Attendance tracking is illegal"}, {id:"c", text:"Simulated phishing is the only way to train employees"}, {id:"d", text:"It removes the need for any technical controls"} ],
    correct: "a",
    explanation: "Measuring outcomes (like reduced click rates) reflects whether training actually changed behavior, which is more meaningful than simply counting attendance.",
    distractorExplanations: { b: "Attendance tracking isn't illegal; it's just a weaker measure of effectiveness.", c: "Simulated phishing is one useful method, not the only way to train employees.", d: "Awareness training complements, but doesn't replace, technical controls." } },
  { id: "q-d5-13", domainId: "d5", tag: "d5-flagship", type: "single",
    prompt: "Which document identifies an organization's most critical business functions, their dependencies, and feeds into RTO/RPO targets?",
    choices: [ {id:"a", text:"Business Impact Analysis (BIA)"}, {id:"b", text:"Risk register"}, {id:"c", text:"Rules of engagement"}, {id:"d", text:"Non-Disclosure Agreement"} ],
    correct: "a",
    explanation: "A Business Impact Analysis identifies critical business functions and dependencies, informing recovery targets like RTO/RPO.",
    distractorExplanations: { b: "A risk register tracks identified risks broadly, not specifically critical function dependencies.", c: "Rules of engagement define test boundaries, unrelated to business continuity planning.", d: "An NDA protects confidentiality, unrelated to business continuity planning." } },
  { id: "q-d5-14", domainId: "d5", tag: "d5-t4", type: "single",
    prompt: "Which statement about compliance is most accurate?",
    choices: [ {id:"a", text:"Compliance requires ongoing monitoring and reporting, not a one-time checkbox"}, {id:"b", text:"Once an organization is compliant, no further review is ever needed"}, {id:"c", text:"Compliance and security are exactly the same thing"}, {id:"d", text:"Compliance only applies to publicly traded companies"} ],
    correct: "a",
    explanation: "Compliance is an ongoing responsibility requiring continuous monitoring and reporting, not a one-time achievement.",
    distractorExplanations: { b: "Compliance requires continuous review as regulations, systems, and practices change.", c: "Compliance and security overlap but are not identical — a system can be compliant yet still have security gaps, or secure yet not meet a specific regulation.", d: "Compliance requirements can apply to many types of organizations, not only publicly traded companies." } },
  { id: "q-d5-15", domainId: "d5", tag: "d5-flagship", type: "single",
    prompt: "Which risk analysis approach uses relative ratings like low/medium/high rather than specific monetary figures?",
    choices: [ {id:"a", text:"Qualitative risk analysis"}, {id:"b", text:"Quantitative risk analysis"}, {id:"c", text:"ALE calculation"}, {id:"d", text:"CVSS scoring"} ],
    correct: "a",
    explanation: "Qualitative risk analysis uses relative, subjective ratings (low/medium/high) rather than specific monetary values.",
    distractorExplanations: { b: "Quantitative analysis uses real numbers like SLE/ARO/ALE, the opposite of this approach.", c: "ALE calculation is itself a quantitative technique, not the relative-rating approach described.", d: "CVSS scoring rates vulnerability severity numerically, a different context than general risk treatment analysis." } },
  { id: "q-d5-16", domainId: "d5", tag: "d5-t3", type: "single",
    prompt: "A company signs an agreement with a vendor defining guaranteed uptime and response times for a service. This is a:",
    choices: [ {id:"a", text:"Service Level Agreement (SLA)"}, {id:"b", text:"Non-Disclosure Agreement (NDA)"}, {id:"c", text:"Rules of engagement"}, {id:"d", text:"Risk register"} ],
    correct: "a",
    explanation: "An SLA defines expected service performance guarantees, such as uptime and response times.",
    distractorExplanations: { b: "An NDA protects confidential information, not performance guarantees.", c: "Rules of engagement define testing boundaries, unrelated to vendor service guarantees.", d: "A risk register tracks organizational risks, unrelated to vendor performance agreements." } },

  // ---------- DOMAIN 1 (continued, +8) ----------
  { id: "q-d1-11", domainId: "d1", tag: "d1-t2", type: "single",
    prompt: "A company implements redundant power supplies and offsite backups for its critical database server. Which part of the CIA triad does this primarily address?",
    choices: [ {id:"a", text:"Availability"}, {id:"b", text:"Confidentiality"}, {id:"c", text:"Integrity"}, {id:"d", text:"Non-repudiation"} ],
    correct: "a",
    explanation: "Redundancy and backups keep a system accessible and reduce downtime, which directly supports availability.",
    distractorExplanations: { b: "Confidentiality concerns keeping data secret, not keeping systems running.", c: "Integrity concerns unauthorized modification, not uptime.", d: "Non-repudiation concerns proof of action, unrelated to power/backup redundancy." } },
  { id: "q-d1-12", domainId: "d1", tag: "d1-t2", type: "single",
    prompt: "In a zero trust architecture, which plane is responsible for making the actual policy decision about whether a specific access request should be allowed?",
    choices: [ {id:"a", text:"Control plane"}, {id:"b", text:"Data plane"}, {id:"c", text:"Physical layer"}, {id:"d", text:"Application layer"} ],
    correct: "a",
    explanation: "The control plane makes the access policy decision; the data plane then carries and enforces the actual traffic based on that decision.",
    distractorExplanations: { b: "The data plane carries the traffic after a decision is made — it doesn't decide policy itself.", c: "The physical layer concerns cabling/signaling, unrelated to zero trust policy decisions.", d: "Application layer is an OSI model concept, not part of the zero trust control/data plane split." } },
  { id: "q-d1-13", domainId: "d1", tag: "d1-t3", type: "single",
    prompt: "Before approving a proposed database schema change, a change advisory board asks which other applications and reports depend on the affected tables. This step is called:",
    choices: [ {id:"a", text:"Impact analysis"}, {id:"b", text:"A rollback plan"}, {id:"c", text:"A maintenance window"}, {id:"d", text:"A standard operating procedure"} ],
    correct: "a",
    explanation: "Impact analysis identifies what else could be affected by a proposed change before it's approved.",
    distractorExplanations: { b: "A rollback plan is how to undo the change if it fails, not how to assess dependencies beforehand.", c: "A maintenance window is the scheduled time for the change, not the dependency assessment.", d: "An SOP is a documented repeatable process, not this specific dependency-checking step." } },
  { id: "q-d1-14", domainId: "d1", tag: "d1-t3", type: "single",
    prompt: "A change is applied to a production system and immediately causes errors. The team reverses the change within minutes using a pre-written set of reversal steps. This is an example of:",
    choices: [ {id:"a", text:"A rollback plan"}, {id:"b", text:"A maintenance window"}, {id:"c", text:"A risk register"}, {id:"d", text:"Impact analysis"} ],
    correct: "a",
    explanation: "A rollback plan is a predefined way to undo a change if it causes problems, exactly as described.",
    distractorExplanations: { b: "A maintenance window is the scheduled time period for the change, not the reversal steps.", c: "A risk register tracks identified risks generally, not a specific change's reversal steps.", d: "Impact analysis happens before a change is approved, not during a live reversal." } },
  { id: "q-d1-15", domainId: "d1", tag: "d1-t4", type: "single",
    prompt: "A security engineer chooses bcrypt specifically because it deliberately takes more computational time per password guess than a standard fast hash function. This technique is called:",
    choices: [ {id:"a", text:"Key stretching"}, {id:"b", text:"Salting"}, {id:"c", text:"Tokenization"}, {id:"d", text:"Digital signing"} ],
    correct: "a",
    explanation: "Key stretching deliberately slows down hashing (as bcrypt and PBKDF2 do) to make brute-force password cracking harder.",
    distractorExplanations: { b: "Salting adds random data before hashing to defeat rainbow tables — a related but different technique, often used alongside key stretching.", c: "Tokenization replaces sensitive data with a placeholder token, unrelated to hashing speed.", d: "Digital signing proves authenticity and integrity using asymmetric keys, unrelated to password hashing speed." } },
  { id: "q-d1-16", domainId: "d1", tag: "d1-t4", type: "single",
    prompt: "A browser needs to check, in real time, whether a specific website's certificate has been revoked, without waiting for a periodically updated downloadable list. Which protocol is designed for this?",
    choices: [ {id:"a", text:"OCSP"}, {id:"b", text:"CRL"}, {id:"c", text:"PKI"}, {id:"d", text:"AES"} ],
    correct: "a",
    explanation: "OCSP (Online Certificate Status Protocol) checks a single certificate's revocation status in real time against the CA.",
    distractorExplanations: { b: "A CRL is a downloaded list checked offline/periodically, not a real-time single-certificate check.", c: "PKI is the overall trust system/infrastructure, not the specific real-time revocation check protocol.", d: "AES is a symmetric encryption cipher, unrelated to certificate revocation checking." } },
  { id: "q-d1-17", domainId: "d1", tag: "d1-flagship", type: "single",
    prompt: "A company publishes a mandatory policy requiring all employees to complete a background check before receiving system access. What type of control is this policy itself?",
    choices: [ {id:"a", text:"Directive"}, {id:"b", text:"Preventive"}, {id:"c", text:"Detective"}, {id:"d", text:"Compensating"} ],
    correct: "a",
    explanation: "A control that mandates or directs behavior through policy, like a background-check requirement, is a directive control.",
    distractorExplanations: { b: "Preventive controls technically stop an action outright (like a locked door); this policy directs behavior rather than physically blocking anything itself.", c: "Detective controls identify that something already happened, which doesn't describe a mandate issued in advance.", d: "Compensating controls are stand-ins used when a primary control isn't feasible, not a foundational policy mandate." } },
  { id: "q-d1-18", domainId: "d1", tag: "d1-flagship", type: "single",
    prompt: "After a ransomware incident, an organization restores affected servers from clean backups to resume normal operations. This action is an example of which control function?",
    choices: [ {id:"a", text:"Corrective"}, {id:"b", text:"Compensating"}, {id:"c", text:"Deterrent"}, {id:"d", text:"Directive"} ],
    correct: "a",
    explanation: "Corrective controls fix or limit damage after an incident has occurred — restoring from clean backups is a textbook example.",
    distractorExplanations: { b: "Compensating controls stand in for a primary control that isn't feasible, put in place before an incident, not a post-incident fix.", c: "Deterrent controls only discourage an attempt; they don't describe restoring systems afterward.", d: "Directive controls are policy mandates, not a hands-on recovery action." } },

  // ---------- DOMAIN 2 (continued, +15) ----------
  { id: "q-d2-19", domainId: "d2", tag: "d2-t1", type: "single",
    prompt: "A company discovers that a rival firm's employee attempted to access its unreleased product designs using social engineering. This threat actor is best classified as:",
    choices: [ {id:"a", text:"Competitor"}, {id:"b", text:"Hacktivist"}, {id:"c", text:"Unskilled attacker"}, {id:"d", text:"Shadow IT"} ],
    correct: "a",
    explanation: "A rival firm seeking competitive/industrial advantage through unauthorized access is classified as a competitor threat actor.",
    distractorExplanations: { b: "A hacktivist is driven by ideology, not competitive/industrial advantage.", c: "The scenario describes deliberate targeting, not necessarily low skill.", d: "Shadow IT refers to unapproved technology use within an organization, not an external competitor's actions." } },
  { id: "q-d2-20", domainId: "d2", tag: "d2-t1", type: "single",
    prompt: "An employee accidentally emails a spreadsheet containing customer data to the wrong external recipient, with no malicious intent. This is best described as:",
    choices: [ {id:"a", text:"An unintentional insider threat"}, {id:"b", text:"A hacktivist attack"}, {id:"c", text:"A nation-state attack"}, {id:"d", text:"Shadow IT"} ],
    correct: "a",
    explanation: "Insider threats include unintentional mistakes made by legitimate users with legitimate access, not only malicious action.",
    distractorExplanations: { b: "Hacktivism implies ideological motivation, absent here.", c: "Nation-state implies sophisticated, resourced, intentional activity, not an accidental mistake.", d: "Shadow IT refers to unapproved tools/services, not a misdirected email." } },
  { id: "q-d2-21", domainId: "d2", tag: "d2-t1", type: "single",
    prompt: "An attacker with minimal technical skill uses a freely available hacking tool downloaded online to attempt a basic attack, without understanding how the tool works internally. This actor is best classified as:",
    choices: [ {id:"a", text:"Unskilled attacker"}, {id:"b", text:"Nation-state"}, {id:"c", text:"Organized crime"}, {id:"d", text:"Insider"} ],
    correct: "a",
    explanation: "An unskilled attacker (sometimes called a script kiddie) uses existing tools without deep expertise or understanding.",
    distractorExplanations: { b: "Nation-state actors are highly resourced and sophisticated, the opposite of this description.", c: "Organized crime is typically more professionalized and financially driven than this scenario suggests.", d: "An insider already has legitimate access; this scenario describes an external attacker using a downloaded tool." } },
  { id: "q-d2-22", domainId: "d2", tag: "d2-t2", type: "single",
    prompt: "A company's network is compromised after an attacker exploits a vulnerability in software provided by one of its trusted vendors. This is an example of which type of attack vector?",
    choices: [ {id:"a", text:"Supply chain"}, {id:"b", text:"Removable media"}, {id:"c", text:"Default credentials"}, {id:"d", text:"Open service"} ],
    correct: "a",
    explanation: "A weakness introduced through a trusted vendor's software is a supply-chain attack vector.",
    distractorExplanations: { b: "Removable media refers to physical devices like USB drives, not vendor software.", c: "Default credentials refers to unchanged factory passwords, not a vendor software vulnerability.", d: "An open service refers to an unnecessarily exposed network service, not a vendor supply-chain issue." } },
  { id: "q-d2-23", domainId: "d2", tag: "d2-t2", type: "single",
    prompt: "A server has 30 open network ports, but the application it runs only actually needs 2 of them. What is the most appropriate hardening action?",
    choices: [ {id:"a", text:"Close the 28 unnecessary ports"}, {id:"b", text:"Open additional ports for monitoring"}, {id:"c", text:"Leave all ports open for flexibility"}, {id:"d", text:"Change the server's IP address"} ],
    correct: "a",
    explanation: "Closing unnecessary ports directly reduces the attack surface, a core hardening practice.",
    distractorExplanations: { b: "Opening more ports increases, rather than reduces, the attack surface.", c: "Leaving unnecessary ports open unnecessarily increases exposure with no security benefit.", d: "Changing the IP address doesn't address the underlying unnecessary exposure." } },
  { id: "q-d2-24", domainId: "d2", tag: "d2-t3", type: "single",
    prompt: "An application crashes and unexpectedly allows code execution after receiving input larger than its allocated memory space could hold. This is an example of:",
    choices: [ {id:"a", text:"Buffer overflow"}, {id:"b", text:"SQL injection"}, {id:"c", text:"CSRF"}, {id:"d", text:"Directory traversal"} ],
    correct: "a",
    explanation: "A buffer overflow occurs when a program writes more data than an allocated memory buffer can hold, potentially corrupting memory and enabling code execution.",
    distractorExplanations: { b: "SQL injection involves manipulating a database query with malicious input, not memory allocation.", c: "CSRF tricks a browser into submitting an unwanted request; it doesn't involve memory buffers.", d: "Directory traversal accesses files outside an intended folder, unrelated to memory allocation." } },
  { id: "q-d2-25", domainId: "d2", tag: "d2-t3", type: "single",
    prompt: "A banking application allows a user to submit two withdrawal requests at nearly the same instant, and due to a timing flaw in how the balance check occurs, both requests succeed even though the account only had enough funds for one. This is an example of:",
    choices: [ {id:"a", text:"A race condition"}, {id:"b", text:"A buffer overflow"}, {id:"c", text:"An SSRF vulnerability"}, {id:"d", text:"A zero-day"} ],
    correct: "a",
    explanation: "A race condition is a timing-dependent flaw where the outcome depends on the relative timing of operations — exactly what allows both withdrawals to succeed here.",
    distractorExplanations: { b: "A buffer overflow is a memory-handling flaw, unrelated to request timing.", c: "SSRF tricks a server into making a request on the attacker's behalf, unrelated to this timing flaw.", d: "A zero-day describes disclosure status (unpatched/unknown), not the specific timing-based flaw type." } },
  { id: "q-d2-26", domainId: "d2", tag: "d2-t3", type: "single",
    prompt: "An attacker modifies a URL parameter to include repeated '../' sequences and successfully retrieves a system file outside the web application's intended folder. This is:",
    choices: [ {id:"a", text:"Directory traversal"}, {id:"b", text:"Cross-Site Scripting"}, {id:"c", text:"SSRF"}, {id:"d", text:"Buffer overflow"} ],
    correct: "a",
    explanation: "Directory traversal uses path sequences like '../' to access files outside an application's intended directory.",
    distractorExplanations: { b: "XSS injects malicious script into a page, unrelated to file path manipulation.", c: "SSRF tricks a server into making requests on the attacker's behalf, not accessing local files via path traversal.", d: "A buffer overflow is a memory-handling flaw, unrelated to file path manipulation." } },
  { id: "q-d2-27", domainId: "d2", tag: "d2-t3", type: "single",
    prompt: "A misconfigured cloud storage bucket is left publicly accessible, exposing sensitive files to anyone with the link. This is best categorized as:",
    choices: [ {id:"a", text:"A cloud misconfiguration vulnerability"}, {id:"b", text:"A zero-day vulnerability"}, {id:"c", text:"A race condition"}, {id:"d", text:"A buffer overflow"} ],
    correct: "a",
    explanation: "Publicly exposed cloud storage due to incorrect settings is a classic cloud misconfiguration vulnerability, not a software flaw.",
    distractorExplanations: { b: "A zero-day is an unknown/unpatched software vulnerability, not a configuration mistake.", c: "A race condition is a timing-dependent flaw, unrelated to storage permission settings.", d: "A buffer overflow is a memory-handling flaw, unrelated to cloud storage configuration." } },
  { id: "q-d2-28", domainId: "d2", tag: "d2-t4", type: "single",
    prompt: "An employee downloads a 'free' PDF converter tool that, once installed, secretly gives an attacker remote access to the machine. The tool itself performed no PDF conversion at all. This is an example of:",
    choices: [ {id:"a", text:"Trojan"}, {id:"b", text:"Worm"}, {id:"c", text:"Rootkit"}, {id:"d", text:"Spyware"} ],
    correct: "a",
    explanation: "A trojan disguises itself as legitimate, useful software to trick a user into installing it — exactly this scenario.",
    distractorExplanations: { b: "A worm self-replicates across a network without needing the user to install anything.", c: "A rootkit's defining trait is hiding deep in the OS to maintain access, not tricking a user into installing it.", d: "Spyware's defining trait is secretly gathering information, which isn't the focus of this disguised-install scenario." } },
  { id: "q-d2-29", domainId: "d2", tag: "d2-t4", type: "single",
    prompt: "Malware silently records every key a user presses, including their online banking password, and sends this data to an attacker. This is an example of:",
    choices: [ {id:"a", text:"A keylogger"}, {id:"b", text:"A worm"}, {id:"c", text:"Ransomware"}, {id:"d", text:"A rootkit"} ],
    correct: "a",
    explanation: "A keylogger captures and records keystrokes, often specifically to steal credentials like this.",
    distractorExplanations: { b: "A worm's defining trait is self-replication across a network, not keystroke capture.", c: "Ransomware's defining trait is encrypting data for ransom, not silently logging keystrokes.", d: "A rootkit's defining trait is hiding to maintain access, not specifically capturing keystrokes." } },
  { id: "q-d2-30", domainId: "d2", tag: "d2-t4", type: "single",
    prompt: "An attacker runs a tool that tries thousands of common real-world words and phrases as potential passwords against a single user account. This is an example of:",
    choices: [ {id:"a", text:"A dictionary attack"}, {id:"b", text:"Password spraying"}, {id:"c", text:"Credential stuffing"}, {id:"d", text:"A rainbow table attack"} ],
    correct: "a",
    explanation: "A dictionary attack tries common words/phrases against one account, exactly as described.",
    distractorExplanations: { b: "Password spraying tries one password across MANY accounts, the reverse pattern of this scenario.", c: "Credential stuffing reuses previously leaked real credentials, not a wordlist of common terms.", d: "A rainbow table attack reverses stolen password hashes using precomputed tables, a different technique entirely." } },
  { id: "q-d2-31", domainId: "d2", tag: "d2-t4", type: "single",
    prompt: "An attacker steals a database of unsalted password hashes and uses a precomputed table of hash values to quickly reverse them back into plaintext passwords. This technique is called:",
    choices: [ {id:"a", text:"A rainbow table attack"}, {id:"b", text:"A dictionary attack"}, {id:"c", text:"Password spraying"}, {id:"d", text:"Credential stuffing"} ],
    correct: "a",
    explanation: "A rainbow table attack uses precomputed hash tables to quickly reverse unsalted password hashes.",
    distractorExplanations: { b: "A dictionary attack guesses passwords directly against a live login, not reversing stolen hashes.", c: "Password spraying targets live account logins, not offline hash reversal.", d: "Credential stuffing reuses leaked plaintext-equivalent credentials elsewhere, not reversing hashes via precomputed tables." } },
  { id: "q-d2-32", domainId: "d2", tag: "d2-t4", type: "single",
    prompt: "An attacker sets up a wireless access point using the same network name as a coffee shop's legitimate Wi-Fi, hoping customers connect to it instead. This is an example of:",
    choices: [ {id:"a", text:"An evil twin attack"}, {id:"b", text:"DNS poisoning"}, {id:"c", text:"An on-path attack"}, {id:"d", text:"A DDoS attack"} ],
    correct: "a",
    explanation: "An evil twin is a fake wireless access point mimicking a legitimate one to trick users into connecting.",
    distractorExplanations: { b: "DNS poisoning corrupts DNS resolution data; it doesn't describe setting up a fake access point.", c: "An on-path attack describes intercepting traffic between two parties generally; this scenario specifically describes the evil twin setup technique.", d: "A DDoS attack overwhelms a target to deny service, unrelated to mimicking a Wi-Fi network name." } },
  { id: "q-d2-33", domainId: "d2", tag: "d2-t5", type: "single",
    prompt: "After a critical vulnerability is disclosed in a web server's software, which single action most directly addresses that specific vulnerability?",
    choices: [ {id:"a", text:"Applying the vendor's patch"}, {id:"b", text:"Enabling a host firewall"}, {id:"c", text:"Conducting user training"}, {id:"d", text:"Segmenting the network"} ],
    correct: "a",
    explanation: "Patching closes the specific known vulnerability directly — the other options are valuable general controls but don't fix that particular flaw.",
    distractorExplanations: { b: "A host firewall is a valuable general control but doesn't remove the underlying software flaw itself.", c: "User training addresses social engineering risk, not a specific unpatched software vulnerability.", d: "Segmentation limits lateral movement after a compromise but doesn't fix the vulnerability itself." } },

  // ---------- DOMAIN 3 (continued, +13) ----------
  { id: "q-d3-15", domainId: "d3", tag: "d3-t1", type: "single",
    prompt: "A development team wants to deploy many small, fast-starting application instances that share the host operating system's kernel rather than each running a full separate OS. Which technology fits this need?",
    choices: [ {id:"a", text:"Containers"}, {id:"b", text:"Virtual machines"}, {id:"c", text:"Bare-metal servers"}, {id:"d", text:"ICS/SCADA"} ],
    correct: "a",
    explanation: "Containers share the host OS kernel, making them lightweight and fast to start compared to full virtual machines.",
    distractorExplanations: { b: "VMs each include a full guest OS, making them heavier and slower to start than containers.", c: "Bare-metal servers run directly on hardware with no virtualization layer at all.", d: "ICS/SCADA refers to industrial control systems, unrelated to lightweight application deployment." } },
  { id: "q-d3-16", domainId: "d3", tag: "d3-t1", type: "single",
    prompt: "A company deploys code that runs only when triggered, is billed per execution, and requires no server management on the company's part. This is an example of:",
    choices: [ {id:"a", text:"Serverless computing"}, {id:"b", text:"Infrastructure as a Service"}, {id:"c", text:"On-premises hosting"}, {id:"d", text:"A hot site"} ],
    correct: "a",
    explanation: "Serverless computing removes server management entirely, running code only when triggered and billing per execution.",
    distractorExplanations: { b: "IaaS still requires the customer to manage the OS and above, unlike serverless.", c: "On-premises hosting means the company manages its own physical servers, the opposite of serverless.", d: "A hot site is a disaster-recovery facility concept, unrelated to this compute model." } },
  { id: "q-d3-17", domainId: "d3", tag: "d3-t1", type: "single",
    prompt: "A team defines its entire cloud environment in version-controlled configuration files, so the exact same infrastructure can be reliably recreated from that code at any time. This practice is called:",
    choices: [ {id:"a", text:"Infrastructure as Code"}, {id:"b", text:"Virtualization"}, {id:"c", text:"Edge computing"}, {id:"d", text:"A screened subnet"} ],
    correct: "a",
    explanation: "Infrastructure as Code defines and provisions infrastructure through version-controlled code rather than manual configuration.",
    distractorExplanations: { b: "Virtualization is the underlying technology that creates VMs, not the practice of defining infrastructure as code.", c: "Edge computing processes data near its source, unrelated to version-controlled infrastructure definitions.", d: "A screened subnet (DMZ) is a network zone, not an infrastructure-provisioning practice." } },
  { id: "q-d3-18", domainId: "d3", tag: "d3-t1", type: "single",
    prompt: "In a PaaS (Platform as a Service) model, which of the following is typically the CUSTOMER's responsibility, not the provider's?",
    choices: [ {id:"a", text:"The application code running on the platform"}, {id:"b", text:"Patching the underlying operating system"}, {id:"c", text:"Maintaining the physical data center"}, {id:"d", text:"Managing the hypervisor"} ],
    correct: "a",
    explanation: "In PaaS, the provider manages the hardware, OS, and runtime, while the customer remains responsible for their own application code, data, and access.",
    distractorExplanations: { b: "Patching the underlying OS is the provider's responsibility in PaaS.", c: "Maintaining the physical data center is always the provider's responsibility in any cloud model.", d: "Managing the hypervisor is the provider's responsibility, not the customer's." } },
  { id: "q-d3-19", domainId: "d3", tag: "d3-t3", type: "single",
    prompt: "A company reaches the end of a document's required retention period and permanently and securely destroys it according to policy. This is part of which stage of the data lifecycle?",
    choices: [ {id:"a", text:"Destruction"}, {id:"b", text:"Creation"}, {id:"c", text:"Sharing"}, {id:"d", text:"Archival"} ],
    correct: "a",
    explanation: "Destruction is the final stage of the data lifecycle, where data is permanently and securely disposed of once no longer needed.",
    distractorExplanations: { b: "Creation is the first stage, when data is first generated, not destroyed.", c: "Sharing refers to distributing data to others, unrelated to end-of-life destruction.", d: "Archival refers to long-term storage before eventual destruction, not the destruction step itself." } },
  { id: "q-d3-20", domainId: "d3", tag: "d3-t3", type: "single",
    prompt: "A regulation requires that a hospital's patient records remain physically stored on servers located within its own country's borders. This requirement is an example of:",
    choices: [ {id:"a", text:"Data sovereignty"}, {id:"b", text:"Data masking"}, {id:"c", text:"Tokenization"}, {id:"d", text:"Data classification"} ],
    correct: "a",
    explanation: "Data sovereignty concerns where data is legally allowed to be stored and which country's laws apply.",
    distractorExplanations: { b: "Data masking hides part of a displayed value, unrelated to physical storage location.", c: "Tokenization replaces sensitive values with tokens, unrelated to storage location requirements.", d: "Data classification labels data by sensitivity, a separate concept from where it may be stored." } },
  { id: "q-d3-21", domainId: "d3", tag: "d3-t4", type: "single",
    prompt: "A server cluster is designed so that if one node fails, the remaining nodes automatically continue serving requests without interruption, though possibly at reduced capacity. This describes:",
    choices: [ {id:"a", text:"Fault tolerance"}, {id:"b", text:"Geographic dispersion"}, {id:"c", text:"A cold site"}, {id:"d", text:"An RPO target"} ],
    correct: "a",
    explanation: "Fault tolerance lets a system keep functioning, possibly in a degraded state, despite a component failure.",
    distractorExplanations: { b: "Geographic dispersion spreads resources across physical locations, a different resilience technique than same-site clustering.", c: "A cold site is a disaster-recovery facility tier, not a clustering behavior.", d: "An RPO target is a data-loss metric, not a description of cluster failover behavior." } },
  { id: "q-d3-22", domainId: "d3", tag: "d3-t4", type: "single",
    prompt: "A company hosts identical copies of its critical application in data centers on two different continents, so that a natural disaster affecting one region doesn't take the whole service down. This is an example of:",
    choices: [ {id:"a", text:"Geographic dispersion"}, {id:"b", text:"Fault tolerance"}, {id:"c", text:"A warm site"}, {id:"d", text:"MTTR reduction"} ],
    correct: "a",
    explanation: "Geographic dispersion spreads resources across multiple physical locations so a regional disaster doesn't take everything down at once.",
    distractorExplanations: { b: "Fault tolerance concerns surviving a component failure, not specifically spreading resources across regions.", c: "A warm site is a specific disaster-recovery facility tier, not this general multi-continent design.", d: "MTTR reduction concerns repair speed, unrelated to geographic distribution of resources." } },
  { id: "q-d3-23", domainId: "d3", tag: "d3-t4", type: "single",
    prompt: "A company's backups run once every 24 hours. If a failure occurs right before the next scheduled backup, approximately how much data could be lost, and what metric does this describe?",
    choices: [ {id:"a", text:"Up to 24 hours of data could be lost — this describes the RPO"}, {id:"b", text:"Up to 24 hours of downtime — this describes the RTO"}, {id:"c", text:"Zero data loss, because RPO only applies to downtime"}, {id:"d", text:"This describes MTBF, not RPO"} ],
    correct: "a",
    explanation: "RPO (Recovery Point Objective) measures acceptable data loss — with daily backups, up to 24 hours of data could be lost in the worst case.",
    distractorExplanations: { b: "RTO measures downtime, a different metric than the data-loss scenario described here.", c: "This is incorrect — RPO specifically measures potential data loss, not downtime.", d: "MTBF measures how often failures occur, not the amount of data that could be lost from a backup gap." } },
  { id: "q-d3-24", domainId: "d3", tag: "d3-t2b", type: "single",
    prompt: "A company places a device in front of its internal web servers that receives all incoming customer requests and forwards them to the appropriate backend server, without exposing the backend servers directly. This device is acting as a:",
    choices: [ {id:"a", text:"Reverse proxy"}, {id:"b", text:"Forward proxy"}, {id:"c", text:"VPN concentrator"}, {id:"d", text:"DNS resolver"} ],
    correct: "a",
    explanation: "A reverse proxy sits in front of internal servers, handling incoming requests on their behalf and shielding them from direct exposure.",
    distractorExplanations: { b: "A forward proxy protects outbound traffic from internal users, not inbound traffic to internal servers.", c: "A VPN concentrator terminates VPN connections, unrelated to forwarding web requests.", d: "A DNS resolver handles name resolution, not request forwarding to backend servers." } },
  { id: "q-d3-25", domainId: "d3", tag: "d3-t2b", type: "single",
    prompt: "A remote employee connects to a specific internal application through a solution that grants access to only that one application, without placing the employee's device fully inside the corporate network. This describes:",
    choices: [ {id:"a", text:"Zero Trust Network Access (ZTNA)"}, {id:"b", text:"A traditional full-tunnel VPN"}, {id:"c", text:"NAT"}, {id:"d", text:"A DMZ"} ],
    correct: "a",
    explanation: "ZTNA grants access to specific applications only, without placing the remote user fully inside the network, unlike a traditional VPN.",
    distractorExplanations: { b: "A traditional full-tunnel VPN typically grants broad network access, not access limited to one specific application.", c: "NAT translates addresses for Internet access, unrelated to remote application access control.", d: "A DMZ is a network zone for public-facing services, not a remote access method." } },
  { id: "q-d3-26", domainId: "d3", tag: "d3-flagship", type: "single",
    prompt: "A company's internal database server is compromised after an attacker pivoted from a public-facing web server that had unrestricted access to it. What architectural change would have most directly limited this?",
    choices: [ {id:"a", text:"Restricting the DMZ web server to only the specific port/protocol the database actually requires"}, {id:"b", text:"Adding more RAM to the web server"}, {id:"c", text:"Changing the database's admin password only"}, {id:"d", text:"Disabling the company's public website entirely"} ],
    correct: "a",
    explanation: "Restricting the DMZ-to-database connection to only the specific required port/protocol limits exactly the kind of unrestricted pivot described, consistent with defense in depth.",
    distractorExplanations: { b: "Adding RAM addresses performance, not unrestricted network access between zones.", c: "Changing one password doesn't address the underlying unrestricted network path that allowed the pivot.", d: "Disabling the website avoids the specific incident but isn't a realistic or targeted architectural fix." } },
  { id: "q-d3-27", domainId: "d3", tag: "d3-flagship", type: "single",
    prompt: "A company's ICS/SCADA control system has no network connection whatsoever to the corporate IT network or the Internet. This is best described as:",
    choices: [ {id:"a", text:"Isolation (an air gap)"}, {id:"b", text:"Segmentation"}, {id:"c", text:"A DMZ"}, {id:"d", text:"Load balancing"} ],
    correct: "a",
    explanation: "Isolation (an air gap) means a system has no network connectivity to the rest of the network at all — a step further than segmentation, which still allows controlled communication.",
    distractorExplanations: { b: "Segmentation divides a network into zones that can still communicate through controlled paths, unlike this fully disconnected scenario.", c: "A DMZ intentionally allows some controlled traffic from the Internet, the opposite of a fully air-gapped system.", d: "Load balancing distributes traffic across servers, unrelated to network connectivity isolation." } },

  // ---------- DOMAIN 4 (continued, +20) ----------
  { id: "q-d4-23", domainId: "d4", tag: "d4-t1", type: "single",
    prompt: "Before a new server image is approved for company-wide deployment, it is configured to a documented, known-good starting state with unnecessary services disabled. This starting state is called:",
    choices: [ {id:"a", text:"A secure baseline"}, {id:"b", text:"A risk register"}, {id:"c", text:"A playbook"}, {id:"d", text:"A rollback plan"} ],
    correct: "a",
    explanation: "A secure baseline is the documented, hardened, known-good starting configuration new systems are built from.",
    distractorExplanations: { b: "A risk register tracks identified risks, unrelated to a system's starting configuration.", c: "A playbook defines incident response steps, not a base configuration.", d: "A rollback plan is for undoing changes, not describing a baseline configuration." } },
  { id: "q-d4-24", domainId: "d4", tag: "d4-t1", type: "single",
    prompt: "Employees are given a list of three company-approved laptop models to choose from, but the company retains ownership and full management control of whichever one is selected. This device strategy is:",
    choices: [ {id:"a", text:"CYOD"}, {id:"b", text:"BYOD"}, {id:"c", text:"COPE (with a fixed personal-use policy)"}, {id:"d", text:"Shadow IT"} ],
    correct: "a",
    explanation: "CYOD (Choose Your Own Device) lets employees select from a company-approved list while the company retains ownership and control.",
    distractorExplanations: { b: "BYOD means the employee owns the device, not the company.", c: "COPE describes company-owned devices with personal use allowed, which isn't emphasized in this scenario's selection-from-a-list framing.", d: "Shadow IT refers to unapproved technology use, the opposite of a formally approved device list." } },
  { id: "q-d4-25", domainId: "d4", tag: "d4-t1", type: "single",
    prompt: "A company remotely wipes a lost company-owned phone the moment it's reported missing, without needing the employee's cooperation. Which tool most directly enables this capability?",
    choices: [ {id:"a", text:"MDM (Mobile Device Management)"}, {id:"b", text:"DLP"}, {id:"c", text:"NAC"}, {id:"d", text:"SIEM"} ],
    correct: "a",
    explanation: "MDM software enforces security policy on mobile devices, including remote wipe capability for lost or stolen devices.",
    distractorExplanations: { b: "DLP prevents sensitive data from leaving an organization improperly, not remote device wiping.", c: "NAC controls network access based on device posture, not remote wipe capability.", d: "SIEM aggregates and correlates logs, unrelated to remote device management actions." } },
  { id: "q-d4-26", domainId: "d4", tag: "d4-t2", type: "single",
    prompt: "A vulnerability scan discovers a server on the network that IT had no record of and had never inventoried. This finding is best described as a failure of:",
    choices: [ {id:"a", text:"Asset management"}, {id:"b", text:"Change management"}, {id:"c", text:"Risk transfer"}, {id:"d", text:"Security awareness"} ],
    correct: "a",
    explanation: "An unmanaged, uninventoried asset is a direct asset management failure — you can't secure what you don't know you have.",
    distractorExplanations: { b: "Change management concerns the process for approved changes, not undiscovered inventory gaps.", c: "Risk transfer is a risk treatment option, unrelated to inventory tracking.", d: "Security awareness concerns employee training, unrelated to asset inventory." } },
  { id: "q-d4-27", domainId: "d4", tag: "d4-t2", type: "single",
    prompt: "A company physically shreds old hard drives containing highly sensitive data instead of simply reformatting them before disposal. This is an example of:",
    choices: [ {id:"a", text:"Sanitization"}, {id:"b", text:"Classification"}, {id:"c", text:"Provisioning"}, {id:"d", text:"Tokenization"} ],
    correct: "a",
    explanation: "Physical destruction is a sanitization method, ensuring data cannot be recovered before disposal.",
    distractorExplanations: { b: "Classification labels data by sensitivity, a separate step from physical disposal.", c: "Provisioning refers to creating accounts/access, unrelated to media disposal.", d: "Tokenization replaces sensitive data with placeholders, unrelated to physical drive destruction." } },
  { id: "q-d4-28", domainId: "d4", tag: "d4-t3", type: "single",
    prompt: "A critical vulnerability is found on a legacy system that cannot be patched immediately without breaking a dependent business process. The security team documents a temporary compensating control and a scheduled future review date instead. This is an example of:",
    choices: [ {id:"a", text:"Exception handling"}, {id:"b", text:"Risk transfer"}, {id:"c", text:"Eradication"}, {id:"d", text:"Provisioning"} ],
    correct: "a",
    explanation: "Exception handling in vulnerability management documents why something can't be fixed immediately, along with a compensating control and review date.",
    distractorExplanations: { b: "Risk transfer shifts financial impact to another party (like insurance), not this documented technical exception process.", c: "Eradication is an incident-response term for removing a root cause, not vulnerability exception handling.", d: "Provisioning refers to account creation, unrelated to vulnerability exceptions." } },
  { id: "q-d4-29", domainId: "d4", tag: "d4-t3", type: "single",
    prompt: "A vulnerability scan is configured to actively attempt to exploit each finding to confirm it's real, rather than just checking for indicators. What is the main operational risk of this approach?",
    choices: [ {id:"a", text:"It can disrupt or crash production systems during the scan"}, {id:"b", text:"It always produces more false positives"}, {id:"c", text:"It cannot be run against Internet-facing systems"}, {id:"d", text:"It doesn't require authorization"} ],
    correct: "a",
    explanation: "Intrusive scanning actively attempts exploitation, which carries real risk of disrupting or crashing production systems — this is why it needs explicit authorization.",
    distractorExplanations: { b: "Intrusive scanning generally confirms real exploitability, typically reducing false positives compared to non-intrusive checks, not increasing them.", c: "Intrusive scans can technically be run against Internet-facing systems, though usually with great caution and authorization.", d: "Intrusive scanning absolutely requires explicit authorization, given its disruption risk — the opposite of this statement." } },
  { id: "q-d4-30", domainId: "d4", tag: "d4-t4", type: "single",
    prompt: "A SIEM flags a login attempt as suspicious because it deviates from the account's normal established login times and locations. What is this 'normal' reference point called?",
    choices: [ {id:"a", text:"A baseline"}, {id:"b", text:"A playbook"}, {id:"c", text:"A risk register"}, {id:"d", text:"A rollback plan"} ],
    correct: "a",
    explanation: "A baseline is the established picture of normal behavior used to recognize what's abnormal.",
    distractorExplanations: { b: "A playbook defines response steps, not a reference point for normal behavior.", c: "A risk register tracks identified risks, unrelated to login-pattern baselines.", d: "A rollback plan is for undoing changes, unrelated to behavioral baselines." } },
  { id: "q-d4-31", domainId: "d4", tag: "d4-t4", type: "single",
    prompt: "An analyst wants a high-level summary of which hosts communicated with which other hosts, how much data was transferred, and over which ports — without needing the full content of every packet. Which data source best fits this need?",
    choices: [ {id:"a", text:"NetFlow"}, {id:"b", text:"A full packet capture"}, {id:"c", text:"A CVSS score"}, {id:"d", text:"A risk register"} ],
    correct: "a",
    explanation: "NetFlow provides summarized traffic flow information (who talked to whom, how much, over which ports) without full packet content.",
    distractorExplanations: { b: "A full packet capture provides complete raw content, more detail than needed for a high-level traffic summary.", c: "A CVSS score rates vulnerability severity, unrelated to traffic flow summaries.", d: "A risk register tracks organizational risks, unrelated to network traffic data." } },
  { id: "q-d4-32", domainId: "d4", tag: "d4-t5", type: "single",
    prompt: "A company blocks employee access to a category of known-malicious and inappropriate websites at the network level, before any request even reaches those sites. This control is an example of:",
    choices: [ {id:"a", text:"Web/DNS filtering"}, {id:"b", text:"DLP"}, {id:"c", text:"NAC"}, {id:"d", text:"EDR"} ],
    correct: "a",
    explanation: "Web/DNS filtering blocks access to malicious or inappropriate destinations before a connection is even made.",
    distractorExplanations: { b: "DLP blocks sensitive data from leaving the organization, not blocking access to external websites.", c: "NAC verifies device posture before granting network access, unrelated to website category filtering.", d: "EDR focuses on endpoint detection and response, not network-level website filtering." } },
  { id: "q-d4-33", domainId: "d4", tag: "d4-t5", type: "single",
    prompt: "An EDR tool automatically disconnects a workstation from the network the moment it detects a high-confidence ransomware behavior pattern. This response most closely matches which function?",
    choices: [ {id:"a", text:"Containment"}, {id:"b", text:"Detection only"}, {id:"c", text:"Risk acceptance"}, {id:"d", text:"Asset provisioning"} ],
    correct: "a",
    explanation: "Automatically isolating an infected workstation to limit spread is a containment action.",
    distractorExplanations: { b: "This goes beyond detection alone — the tool takes an active isolating action, not just alerting.", c: "Risk acceptance means taking no further action, the opposite of an active isolation response.", d: "Asset provisioning refers to setting up new accounts/access, unrelated to isolating a compromised device." } },
  { id: "q-d4-34", domainId: "d4", tag: "d4-t6", type: "single",
    prompt: "An administrator requests temporary elevated database access through a PAM tool, which automatically expires the elevated permission after four hours regardless of whether it was used. This is an example of:",
    choices: [ {id:"a", text:"Just-in-time access"}, {id:"b", text:"Federation"}, {id:"c", text:"Single sign-on"}, {id:"d", text:"Provisioning"} ],
    correct: "a",
    explanation: "Just-in-time access grants temporary, automatically-expiring elevated access only when needed, exactly as described.",
    distractorExplanations: { b: "Federation extends identity trust across systems/organizations, unrelated to temporary elevated permission windows.", c: "SSO lets one login access multiple systems, unrelated to temporary privilege elevation.", d: "Provisioning is the initial creation of an account, not a temporary elevated-access grant." } },
  { id: "q-d4-35", domainId: "d4", tag: "d4-t6", type: "single",
    prompt: "A company requires employees to enter a password AND scan their fingerprint to log in. Which two MFA factor categories does this combine?",
    choices: [ {id:"a", text:"Something you know and something you are"}, {id:"b", text:"Something you have and something you are"}, {id:"c", text:"Something you know and something you have"}, {id:"d", text:"Somewhere you are and something you do"} ],
    correct: "a",
    explanation: "A password is something you know, and a fingerprint is something you are — this combines those two factor categories.",
    distractorExplanations: { b: "This pairing would describe a token/device plus a biometric, not a password plus a fingerprint.", c: "This pairing would describe a password plus a physical token/device, not a fingerprint.", d: "Location and behavior-based factors aren't what's described here — a password and fingerprint are used instead." } },
  { id: "q-d4-36", domainId: "d4", tag: "d4-t6", type: "single",
    prompt: "A university student logs into a partner research library's website using their university credentials, without creating a brand-new separate account there. This is an example of:",
    choices: [ {id:"a", text:"Federation"}, {id:"b", text:"Provisioning"}, {id:"c", text:"Just-in-time access"}, {id:"d", text:"Privileged access management"} ],
    correct: "a",
    explanation: "Federation extends an established identity to work across separate organizations, exactly as described.",
    distractorExplanations: { b: "Provisioning is creating a new account within one system, the opposite of reusing an existing identity elsewhere.", c: "Just-in-time access concerns temporary elevated permissions, unrelated to cross-organization identity trust.", d: "PAM concerns controlling privileged/admin accounts, unrelated to student identity federation." } },
  { id: "q-d4-37", domainId: "d4", tag: "d4-t7", type: "single",
    prompt: "A security workflow automatically correlates a SIEM alert, isolates the affected endpoint via EDR, creates a ticket, and notifies the on-call analyst — all as one coordinated sequence spanning multiple tools. This coordinated sequence is best described as:",
    choices: [ {id:"a", text:"Orchestration"}, {id:"b", text:"A single automated task"}, {id:"c", text:"A secure baseline"}, {id:"d", text:"A gap assessment"} ],
    correct: "a",
    explanation: "Orchestration coordinates multiple automated steps and tools together into one coherent workflow, as described.",
    distractorExplanations: { b: "A single automated task handles one repeatable action, not this multi-tool coordinated sequence.", c: "A secure baseline is a system configuration standard, unrelated to workflow coordination.", d: "A gap assessment compares current state to a standard, unrelated to this operational workflow." } },
  { id: "q-d4-38", domainId: "d4", tag: "d4-t7", type: "single",
    prompt: "A SOAR platform is granted full domain administrator rights so it can perform any possible remediation action automatically. What is the main risk of this configuration?",
    choices: [ {id:"a", text:"If the automation tool is compromised or misconfigured, it can now act with excessive privilege at scale"}, {id:"b", text:"It will run too slowly to be useful"}, {id:"c", text:"It cannot integrate with a SIEM"}, {id:"d", text:"It eliminates the need for any further security controls"} ],
    correct: "a",
    explanation: "Granting excessive privilege to an automation tool means a compromise or misconfiguration of that tool can now cause damage at scale — a core automation risk.",
    distractorExplanations: { b: "Excessive privilege doesn't inherently slow down automation speed.", c: "Excessive privilege doesn't prevent SIEM integration — these are unrelated.", d: "No automation tool, however privileged, eliminates the need for other security controls." } },
  { id: "q-d4-39", domainId: "d4", tag: "d4-t9", type: "single",
    prompt: "An analyst wants to know exactly which URLs were requested on a company's public website and from which IP addresses, to investigate a possible web application attack. Which log source answers this directly?",
    choices: [ {id:"a", text:"Web server/application logs"}, {id:"b", text:"DHCP logs"}, {id:"c", text:"DNS logs"}, {id:"d", text:"Authentication logs"} ],
    correct: "a",
    explanation: "Web server/application logs record exactly which requests (URLs) were made and from which source IPs.",
    distractorExplanations: { b: "DHCP logs show which device held which IP address, not web requests made.", c: "DNS logs show domain lookups, not specific URL requests to a web application.", d: "Authentication logs show login activity, not general web requests to public pages." } },
  { id: "q-d4-40", domainId: "d4", tag: "d4-t9", type: "single",
    prompt: "An analyst needs to examine the exact raw content of network traffic, byte for byte, to understand precisely what data was exchanged during a suspicious connection. Which data source provides this level of detail?",
    choices: [ {id:"a", text:"A full packet capture"}, {id:"b", text:"NetFlow"}, {id:"c", text:"A CVSS score"}, {id:"d", text:"A risk register"} ],
    correct: "a",
    explanation: "A full packet capture records the complete raw traffic content, providing byte-level detail beyond what summary logs offer.",
    distractorExplanations: { b: "NetFlow provides summarized flow data (who talked to whom, how much), not full raw packet content.", c: "A CVSS score rates vulnerability severity, unrelated to captured traffic content.", d: "A risk register tracks organizational risks, unrelated to network traffic content." } },
  { id: "q-d4-41", domainId: "d4", tag: "d4-t1", type: "single",
    prompt: "A company allows employees to use personal phones for work email (BYOD) but requires installing an MDM profile that can wipe only the separate work-related data, not the entire personal device. This design choice primarily balances:",
    choices: [ {id:"a", text:"Organizational security control with employee personal privacy"}, {id:"b", text:"Cost savings with network speed"}, {id:"c", text:"Data sovereignty with data masking"}, {id:"d", text:"Federation with single sign-on"} ],
    correct: "a",
    explanation: "A scoped work-profile wipe balances the organization's need for security control over its own data with the employee's personal privacy on their own device.",
    distractorExplanations: { b: "This design choice is about privacy and control, not primarily about cost or network speed.", c: "Data sovereignty and masking concern data location and display, unrelated to this BYOD wipe-scope design.", d: "Federation and SSO concern identity across systems, unrelated to this device-wipe scoping decision." } },
  { id: "q-d4-42", domainId: "d4", tag: "d4-t3", type: "single",
    prompt: "A scan run without any login credentials reports far fewer findings on an internal server than a scan run while logged into that same server. What most likely explains this difference?",
    choices: [ {id:"a", text:"The non-credentialed scan could only see what's visible externally, missing internal configuration issues"}, {id:"b", text:"The credentialed scan is less accurate"}, {id:"c", text:"The server was patched between the two scans"}, {id:"d", text:"Credentialed scans cannot detect any vulnerabilities at all"} ],
    correct: "a",
    explanation: "A non-credentialed scan only sees what's visible from outside, missing internal detail a credentialed (logged-in) scan can see, such as local configuration issues and missing patches.",
    distractorExplanations: { b: "Credentialed scans are generally MORE accurate and detailed, not less.", c: "Nothing in the scenario indicates patching occurred between scans; the difference is explained by scan visibility, not a system change.", d: "Credentialed scans detect more, not zero, vulnerabilities — this statement is false." } },

  // ---------- DOMAIN 5 (continued, +14) ----------
  { id: "q-d5-17", domainId: "d5", tag: "d5-t1", type: "single",
    prompt: "A company publishes a document stating, at a high level, that 'all customer data must be protected from unauthorized access,' without specifying exact technical requirements. This document is a:",
    choices: [ {id:"a", text:"Policy"}, {id:"b", text:"Standard"}, {id:"c", text:"Procedure"}, {id:"d", text:"Guideline"} ],
    correct: "a",
    explanation: "A policy is a mandatory, high-level statement of intent — general in scope, without specific technical detail.",
    distractorExplanations: { b: "A standard would specify the exact technical requirement (like a specific encryption algorithm), which this document does not.", c: "A procedure would list exact step-by-step instructions, which this high-level statement does not.", d: "A guideline is non-mandatory, while this is described as a mandatory statement of intent." } },
  { id: "q-d5-18", domainId: "d5", tag: "d5-t1", type: "single",
    prompt: "A document lists the exact numbered steps an employee must follow, in order, to request access to a restricted system. This document is a:",
    choices: [ {id:"a", text:"Procedure"}, {id:"b", text:"Policy"}, {id:"c", text:"Guideline"}, {id:"d", text:"Risk register"} ],
    correct: "a",
    explanation: "A procedure gives mandatory, sequential, step-by-step instructions for accomplishing a specific task.",
    distractorExplanations: { b: "A policy is a high-level, general statement of intent, not exact numbered steps.", c: "A guideline is non-mandatory advice, while a procedure with numbered steps is mandatory.", d: "A risk register tracks identified risks, unrelated to access-request steps." } },
  { id: "q-d5-19", domainId: "d5", tag: "d5-t3", type: "single",
    prompt: "Before signing a contract with a new cloud vendor, a company sends a detailed security questionnaire and reviews the vendor's independent audit reports. This step is an example of:",
    choices: [ {id:"a", text:"Due diligence"}, {id:"b", text:"Risk acceptance"}, {id:"c", text:"A gap assessment"}, {id:"d", text:"A tabletop exercise"} ],
    correct: "a",
    explanation: "Due diligence is the assessment process performed before selecting a vendor, exactly as described.",
    distractorExplanations: { b: "Risk acceptance is a risk treatment decision, not a pre-selection vendor assessment step.", c: "A gap assessment compares current controls to a standard, a different kind of review than vendor due diligence.", d: "A tabletop exercise is a discussion-based incident scenario walkthrough, unrelated to vendor selection." } },
  { id: "q-d5-20", domainId: "d5", tag: "d5-t3", type: "single",
    prompt: "A vendor and a company sign an agreement specifically to protect confidential information shared between them during a project. This agreement is a:",
    choices: [ {id:"a", text:"NDA"}, {id:"b", text:"SLA"}, {id:"c", text:"MOU"}, {id:"d", text:"Right-to-audit clause"} ],
    correct: "a",
    explanation: "An NDA (Non-Disclosure Agreement) is specifically designed to protect shared confidential information.",
    distractorExplanations: { b: "An SLA defines expected service performance levels, not confidentiality protection.", c: "An MOU is a broader working-relationship agreement, not specifically a confidentiality protection.", d: "A right-to-audit clause allows inspecting a vendor's security practices, unrelated to confidentiality protection specifically." } },
  { id: "q-d5-21", domainId: "d5", tag: "d5-t3", type: "single",
    prompt: "Two organizations sign a broad agreement outlining the general terms of their ongoing working relationship, separate from the specific performance guarantees found in an SLA. This is best described as:",
    choices: [ {id:"a", text:"An MOU/MSA"}, {id:"b", text:"An NDA"}, {id:"c", text:"A right-to-audit clause"}, {id:"d", text:"A risk register"} ],
    correct: "a",
    explanation: "An MOU (Memorandum of Understanding) or MSA (Master Service Agreement) defines the broader working relationship, separate from an SLA's specific performance terms.",
    distractorExplanations: { b: "An NDA protects confidential information specifically, not the broader relationship terms.", c: "A right-to-audit clause is a specific contractual provision, not the broad relationship agreement itself.", d: "A risk register tracks organizational risks, unrelated to vendor relationship agreements." } },
  { id: "q-d5-22", domainId: "d5", tag: "d5-t4", type: "single",
    prompt: "A company collects a customer's phone number for account recovery purposes, then later uses that same number for unrelated marketing calls without new consent. This violates which privacy principle?",
    choices: [ {id:"a", text:"Purpose limitation"}, {id:"b", text:"Data minimization"}, {id:"c", text:"Data sovereignty"}, {id:"d", text:"Non-repudiation"} ],
    correct: "a",
    explanation: "Purpose limitation means using collected data only for the reason it was originally collected — using it for unrelated marketing violates this principle.",
    distractorExplanations: { b: "Data minimization concerns collecting only what's needed in the first place, a different violation than repurposing already-collected data.", c: "Data sovereignty concerns where data is stored, unrelated to repurposing it for marketing.", d: "Non-repudiation concerns proof of action, unrelated to this privacy principle." } },
  { id: "q-d5-23", domainId: "d5", tag: "d5-t4", type: "single",
    prompt: "A company defines exactly how long customer records are kept before being securely deleted, rather than retaining them indefinitely. This reflects which privacy principle?",
    choices: [ {id:"a", text:"A defined retention and deletion timeline"}, {id:"b", text:"Data sovereignty"}, {id:"c", text:"Purpose limitation"}, {id:"d", text:"Right-to-audit"} ],
    correct: "a",
    explanation: "Defined retention and deletion timelines ensure data isn't kept indefinitely just because it's possible to do so.",
    distractorExplanations: { b: "Data sovereignty concerns legal storage location, not how long data is retained.", c: "Purpose limitation concerns using data only for its original stated reason, a different principle than retention timing.", d: "Right-to-audit is a vendor contract term, unrelated to a company's own data retention policy." } },
  { id: "q-d5-24", domainId: "d5", tag: "d5-t4", type: "single",
    prompt: "An organization passed a compliance audit last year but has since changed several systems without reviewing whether they still meet the same requirements. What is the risk here?",
    choices: [ {id:"a", text:"Compliance is an ongoing responsibility — passing a past audit doesn't guarantee current compliance"}, {id:"b", text:"Compliance only needs to be checked once, ever"}, {id:"c", text:"Passing any audit guarantees permanent compliance"}, {id:"d", text:"Compliance and security are exactly the same, so no separate review is needed"} ],
    correct: "a",
    explanation: "Compliance requires ongoing monitoring — changes made after an audit can introduce new gaps that a past audit result doesn't account for.",
    distractorExplanations: { b: "This is false — compliance requires continuous review, not a one-time check.", c: "No audit result is permanent; systems and requirements both keep changing.", d: "Compliance and security overlap but aren't identical, and neither substitutes for ongoing review of the other." } },
  { id: "q-d5-25", domainId: "d5", tag: "d5-t5", type: "single",
    prompt: "Before a company undergoes a formal ISO 27001 certification audit, it compares its current controls against the standard's requirements to find what's missing. This preparatory step is called:",
    choices: [ {id:"a", text:"A gap assessment"}, {id:"b", text:"An external audit"}, {id:"c", text:"A red team exercise"}, {id:"d", text:"A right-to-audit clause"} ],
    correct: "a",
    explanation: "A gap assessment compares current state against a desired standard, identifying what's missing before a formal audit.",
    distractorExplanations: { b: "An external audit is the formal review itself, not this preparatory internal comparison step.", c: "A red team exercise is offensive security testing, unrelated to comparing controls against a compliance standard.", d: "A right-to-audit clause is a vendor contract term, unrelated to a company's own audit preparation." } },
  { id: "q-d5-26", domainId: "d5", tag: "d5-t5", type: "single",
    prompt: "After a red team exercise, the attacking and defending teams meet together to share findings and techniques so both sides improve for next time. This collaborative process is called:",
    choices: [ {id:"a", text:"Purple teaming"}, {id:"b", text:"Blue teaming"}, {id:"c", text:"An external audit"}, {id:"d", text:"A gap assessment"} ],
    correct: "a",
    explanation: "Purple teaming is the deliberate collaboration between red and blue teams to share findings and improve both sides.",
    distractorExplanations: { b: "Blue teaming refers specifically to the defensive team's role, not the collaborative review process.", c: "An external audit is an independent compliance review, unrelated to red/blue team collaboration.", d: "A gap assessment compares controls to a standard, unrelated to this collaborative exercise review." } },
  { id: "q-d5-27", domainId: "d5", tag: "d5-t5", type: "single",
    prompt: "A company's own internal compliance staff reviews its security controls on a quarterly basis, separate from any outside firm. This is an example of:",
    choices: [ {id:"a", text:"An internal audit"}, {id:"b", text:"An external audit"}, {id:"c", text:"A penetration test"}, {id:"d", text:"A vulnerability scan"} ],
    correct: "a",
    explanation: "An internal audit is performed by the organization's own staff, as described here.",
    distractorExplanations: { b: "An external audit is performed by an independent outside firm, not internal staff.", c: "A penetration test involves authorized humans actively attempting exploitation, not a compliance control review.", d: "A vulnerability scan is an automated technical check, not this kind of staff-led compliance review." } },
  { id: "q-d5-28", domainId: "d5", tag: "d5-t6", type: "single",
    prompt: "An office policy requires employees to lock away sensitive physical documents and lock their computer screens whenever they step away from their desk. This is an example of:",
    choices: [ {id:"a", text:"A clean desk policy"}, {id:"b", text:"A phishing simulation"}, {id:"c", text:"Data minimization"}, {id:"d", text:"A gap assessment"} ],
    correct: "a",
    explanation: "A clean desk policy requires securing sensitive physical documents and devices when a workspace is unattended.",
    distractorExplanations: { b: "A phishing simulation tests employee response to simulated phishing emails, unrelated to physical desk security.", c: "Data minimization concerns limiting what data is collected, not physical workspace habits.", d: "A gap assessment compares controls to a standard, unrelated to this specific workplace habit policy." } },
  { id: "q-d5-29", domainId: "d5", tag: "d5-t6", type: "single",
    prompt: "A company tracks its employees' phishing-simulation click rate every month for a year to see whether it's declining. What does a consistently declining click rate best demonstrate?",
    choices: [ {id:"a", text:"The awareness training program is producing a measurable behavioral improvement"}, {id:"b", text:"The company should stop running simulations since risk is now zero"}, {id:"c", text:"Employees are being unfairly tested"}, {id:"d", text:"The company's email filters have improved, not the employees themselves"} ],
    correct: "a",
    explanation: "A declining click rate over time is a real, measurable outcome showing the training program is changing behavior, not just being attended.",
    distractorExplanations: { b: "A declining rate doesn't mean risk is zero — ongoing simulation remains valuable to sustain and verify the improvement.", c: "Simulations are a legitimate, standard measurement method, not an unfair test.", d: "Click rate measures user behavior specifically, separate from email filtering technology performance." } },
  { id: "q-d5-30", domainId: "d5", tag: "d5-flagship", type: "single",
    prompt: "A company purchases cyber insurance specifically to cover the financial cost of a potential future data breach, rather than trying to prevent every possible scenario itself. This risk treatment is:",
    choices: [ {id:"a", text:"Risk transfer"}, {id:"b", text:"Risk avoidance"}, {id:"c", text:"Risk mitigation"}, {id:"d", text:"Risk acceptance"} ],
    correct: "a",
    explanation: "Risk transfer shifts the financial impact of a risk to another party, such as through insurance.",
    distractorExplanations: { b: "Risk avoidance means stopping the risky activity entirely, not insuring against it.", c: "Risk mitigation reduces likelihood or impact with a control, not shifting financial impact elsewhere.", d: "Risk acceptance means taking no further action, while purchasing insurance is an active risk transfer step." } }
];
